export default JSON.parse('{"work":{"id":"zhan-guo-ce","schoolId":"histories","title":"《戰國策》","genreStrategy":"parallel","sourceNote":"以中國哲學書電子化計劃《士禮居叢書》本為經文底本，對校《欽定四庫全書》本、鮑彪注本及何建章《戰國策注釋》。全書依通行本十二國、三十三卷編次。","chapterIds":["zhan-guo-ce_ch-1"],"totalChars":3666,"subtitle":"劉向編定"},"chapters":[{"id":"zhan-guo-ce_ch-1","workId":"zhan-guo-ce","order":1,"title":"東周","difficulty":4,"estimatedMinutes":13,"passageIds":["zhan-guo-ce_ch-1_p-1","zhan-guo-ce_ch-1_p-2","zhan-guo-ce_ch-1_p-3","zhan-guo-ce_ch-1_p-4","zhan-guo-ce_ch-1_p-5","zhan-guo-ce_ch-1_p-6","zhan-guo-ce_ch-1_p-7","zhan-guo-ce_ch-1_p-8","zhan-guo-ce_ch-1_p-9","zhan-guo-ce_ch-1_p-10","zhan-guo-ce_ch-1_p-11","zhan-guo-ce_ch-1_p-12","zhan-guo-ce_ch-1_p-13","zhan-guo-ce_ch-1_p-14","zhan-guo-ce_ch-1_p-15","zhan-guo-ce_ch-1_p-16","zhan-guo-ce_ch-1_p-17","zhan-guo-ce_ch-1_p-18","zhan-guo-ce_ch-1_p-19","zhan-guo-ce_ch-1_p-20","zhan-guo-ce_ch-1_p-21","zhan-guo-ce_ch-1_p-22","zhan-guo-ce_ch-1_p-23","zhan-guo-ce_ch-1_p-24","zhan-guo-ce_ch-1_p-25","zhan-guo-ce_ch-1_p-26","zhan-guo-ce_ch-1_p-27","zhan-guo-ce_ch-1_p-28","zhan-guo-ce_ch-1_p-29"],"tags":[]}],"passages":[{"id":"zhan-guo-ce_ch-1_p-1","chapterId":"zhan-guo-ce_ch-1","order":1,"canonicalText":"秦興師臨周而求九鼎，周君患之，以告顏率。顏率曰：「大王勿憂，臣請東借救於齊。」顏率至齊，謂齊王曰：「夫秦之為無道也，欲興兵臨周而求九鼎，周之君臣，內自盡計，與秦，不若歸之大國。夫存危國，美名也；得九鼎，厚寶也。願大王圖之。」齊王大悅，發師五萬人，使陳臣思將以救周，而秦兵罷。","sentenceIds":["zhan-guo-ce_ch-1_p-1_s-1","zhan-guo-ce_ch-1_p-1_s-2","zhan-guo-ce_ch-1_p-1_s-3","zhan-guo-ce_ch-1_p-1_s-4","zhan-guo-ce_ch-1_p-1_s-5","zhan-guo-ce_ch-1_p-1_s-6","zhan-guo-ce_ch-1_p-1_s-7"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/zhan-guo-ce/zh"}],"readingAid":{"translation":"秦國發兵逼近周朝並求取九鼎，周君對此感到憂慮，將此事告訴顏率。顏率說：「大王不必擔憂，臣請求向東去齊國借兵求救。」顏率到了齊國，對齊王說：「秦國行事無道，想要發兵逼近周朝求取九鼎，周朝的君臣私下商議，認為與其把九鼎給秦國，不如將它歸屬給貴國。拯救危急的國家，是美好的名聲；得到九鼎，是極大的寶物。希望大王能夠考慮此事。」齊王聽了非常高興，派出五萬大軍，派陳臣思作為將領去救援周朝，秦軍因此撤退。","analysis":"【主題與背景】\\\\n本段背景設定在戰國時期，秦國勢力強大，威逼周天子交出象徵天下共主地位的「九鼎」。周天子面對危機無力抵抗，謀臣顏率出使齊國，利用各國間的利益與虛榮心，成功藉齊國之兵力解了周朝之危。\\\\n\\\\n【詞義與名物】\\\\n「九鼎」：相傳大禹收九牧之金鑄造九鼎，象徵九州，是夏商周三代傳國之寶。\\\\n「無道」：指秦國不講道義。\\\\n「圖之」：圖謀、考慮這件事。\\\\n\\\\n【縱橫機謋】\\\\n顏率深諳各國的心理與利益考量。他對齊王不提周朝的孱弱，而是強調「存危國」的道德名聲與「得九鼎」的實質利益。這種將己方危機轉化為對方利益誘惑的說辭，是典型的縱橫家遊說技巧，成功驅使齊國出兵，達到了「借力打力」的效果。"}},{"id":"zhan-guo-ce_ch-1_p-2","chapterId":"zhan-guo-ce_ch-1","order":2,"canonicalText":"齊將求九鼎，周君又患之。顏率曰：「大王勿憂，臣請東解之。」顏率至齊，謂齊王曰：「周賴大國之義，得君臣父子相保也，願獻九鼎，不識大國何塗之從而致齊？」齊王曰：「寡人將寄徑於梁。」顏率曰：「不可。夫梁之君臣欲得九鼎，謀之暉臺之下，少海之上，其日久矣。鼎入梁，必不出。」齊王曰：「寡人將寄徑於楚。」對曰：「不可。楚之君臣欲得九鼎，謀之於葉庭之中，其日久矣。若入楚，鼎必不出。」王曰：「寡人終何塗之從而致之齊？」顏率曰：「弊邑固竊為大王患之。夫鼎者，非效醯壺醬垂耳，可懷挾提挈以至齊者；非效鳥集、烏飛、兔興、馬逝，灕然止於齊者。昔周之伐殷，得九鼎，凡一鼎而九萬人輓之，九九八十一萬人，士卒師徒，器械被具，所以備者稱此。今大王縱有其人，何塗之從而出？臣竊為大王私憂之。」齊王曰：「子之數來者，猶無與耳。」顏率曰：「不敢欺大國，疾定所從出，弊邑遷鼎以待命。」齊王乃止。","sentenceIds":["zhan-guo-ce_ch-1_p-2_s-1","zhan-guo-ce_ch-1_p-2_s-2","zhan-guo-ce_ch-1_p-2_s-3","zhan-guo-ce_ch-1_p-2_s-4","zhan-guo-ce_ch-1_p-2_s-5","zhan-guo-ce_ch-1_p-2_s-6","zhan-guo-ce_ch-1_p-2_s-7","zhan-guo-ce_ch-1_p-2_s-8","zhan-guo-ce_ch-1_p-2_s-9","zhan-guo-ce_ch-1_p-2_s-10","zhan-guo-ce_ch-1_p-2_s-11","zhan-guo-ce_ch-1_p-2_s-12","zhan-guo-ce_ch-1_p-2_s-13","zhan-guo-ce_ch-1_p-2_s-14","zhan-guo-ce_ch-1_p-2_s-15","zhan-guo-ce_ch-1_p-2_s-16","zhan-guo-ce_ch-1_p-2_s-17","zhan-guo-ce_ch-1_p-2_s-18","zhan-guo-ce_ch-1_p-2_s-19","zhan-guo-ce_ch-1_p-2_s-20","zhan-guo-ce_ch-1_p-2_s-21"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/zhan-guo-ce/zh"}],"readingAid":{"translation":"《戰國策・東周》史實記載：「齊將求九鼎，周君又患之。顏率曰：大王勿憂，臣請東解之。顏率至齊，謂……」。本段記述歷史風雲人物事跡、朝代興衰成敗與國家政治外交謀略。","analysis":"【主題與背景】本段選自史學名著《戰國策・東周》。記載重要歷史事件與君臣對答紀實。\\\\n【詞義與名物】經文核心：「齊將求九鼎，周君又患」，展現古代制度、官制與史學史料價值。\\\\n【史學評價】史筆客觀嚴謹，為後世提供了珍貴的歷史經驗與治國借鑑。"}},{"id":"zhan-guo-ce_ch-1_p-3","chapterId":"zhan-guo-ce_ch-1","order":3,"canonicalText":"秦攻宜陽，周君謂趙累曰：「子以為何如？」對曰：「宜陽必拔也。」君曰：「宜陽城方八里，材士十萬，粟支數年，公仲之軍二十萬，景翠以楚之眾，臨山而救之，秦必無功。」對曰：「甘茂，羈旅也，攻宜陽而有功，則周公旦也；無功，則削跡於秦。秦王不聽群臣父兄之義而攻宜陽，宜陽不拔，秦王恥之。臣故曰拔。」君曰：「子為寡人謀，且奈何？」對曰：「君謂景翠曰：『公爵為執圭，官為柱國，戰而勝，則無加焉矣；不勝，則死，不如背秦援宜陽，公進兵。秦恐公之乘其弊也，必以寶事公；公中慕公之為己乘秦也，亦必盡其寶。』」秦拔宜陽，景翠果進兵。秦懼，遽效煮棗；韓氏果亦效重寶。景翠得城於秦，受寶於韓，而德東周。","sentenceIds":["zhan-guo-ce_ch-1_p-3_s-1","zhan-guo-ce_ch-1_p-3_s-2","zhan-guo-ce_ch-1_p-3_s-3","zhan-guo-ce_ch-1_p-3_s-4","zhan-guo-ce_ch-1_p-3_s-5","zhan-guo-ce_ch-1_p-3_s-6","zhan-guo-ce_ch-1_p-3_s-7","zhan-guo-ce_ch-1_p-3_s-8","zhan-guo-ce_ch-1_p-3_s-9","zhan-guo-ce_ch-1_p-3_s-10","zhan-guo-ce_ch-1_p-3_s-11","zhan-guo-ce_ch-1_p-3_s-12","zhan-guo-ce_ch-1_p-3_s-13","zhan-guo-ce_ch-1_p-3_s-14","zhan-guo-ce_ch-1_p-3_s-15","zhan-guo-ce_ch-1_p-3_s-16"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/zhan-guo-ce/zh"}],"readingAid":{"translation":"秦國攻打宜陽，周君對趙累說：「您認為情況會如何？」趙累回答：「宜陽一定會被攻下。」周君說：「宜陽城方圓八里，擁有精兵十萬，糧草能支撐數年；韓國公仲的軍隊有二十萬，加上景翠率領楚軍依山勢駐紮救援，秦國必定無功而返。」趙累回答：「秦將甘茂是個客居秦國的臣子，如果攻下宜陽立下功勞，就能像周公旦那樣權傾一時；若無功而返，就會在秦國失去立足之地。秦王不聽群臣和宗室的勸阻而攻打宜陽，如果攻不下，秦王會以此為恥。所以我認為宜陽一定會被攻下。」周君說：「您為我謀劃一下，現在該怎麼辦？」趙累回答：「您應該派人去對楚將景翠說：『您的爵位已是執圭，官職已是柱國，即使打勝仗，也無法再增加封賞了；如果打敗了，就會死。不如背棄秦國轉而救援宜陽，您出兵吧。秦國害怕您乘機攻擊他們的疲憊之軍，一定會用重寶來討好您；韓國公仲仰慕您為了韓國而趁機攻擊秦國，也一定會把所有的寶物送給您。』」後來秦國果然攻下宜陽，景翠也確實出兵了。秦國感到恐懼，急忙送上煮棗這塊地；韓國果然也送上了重寶。景翠從秦國得到城池，從韓國得到寶物，而且還讓東周對他感恩戴德。","analysis":"【主題與背景】\\\\n本段記述秦國攻打韓國重鎮宜陽的戰役。周君與趙累討論戰局，趙累準確預測秦國必勝，並為周君策劃如何在這場大國博弈中，利用楚國將領景翠的私利，為東周謀取外交空間與利益。\\\\n\\\\n【詞義與名物】\\\\n「羈旅」：指寄居異鄉的人，這裡指甘茂是客卿。\\\\n「削跡」：消除足跡，引申為被驅逐或失去立足之地。\\\\n「執圭、柱國」：楚國的高級爵位與官職，代表極高地位。\\\\n「煮棗」：地名，秦國以此地賄賂楚將景翠。\\\\n\\\\n【縱橫機謋】\\\\n趙累的分析精闢透徹。首先他看穿甘茂的破釜沉舟與秦王的騎虎難下，斷定秦國必勝。接著他獻計利用景翠「勝無可賞，敗則必死」的處境，勸其按兵不動並兩頭勒索。這展現了戰國策士洞悉人性弱點，以利益操弄大國將領，在夾縫中為弱小國家（東周）謀求最大利益的權謀智慧。"}},{"id":"zhan-guo-ce_ch-1_p-4","chapterId":"zhan-guo-ce_ch-1","order":4,"canonicalText":"東周與西周戰，韓救西周。為東周謂韓王曰：「西周者，故天子之國也，多名器重寶。案兵而勿出，可以德東周，西周之寶可盡矣。」","sentenceIds":["zhan-guo-ce_ch-1_p-4_s-1","zhan-guo-ce_ch-1_p-4_s-2","zhan-guo-ce_ch-1_p-4_s-3","zhan-guo-ce_ch-1_p-4_s-4"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/zhan-guo-ce/zh"}],"readingAid":{"translation":"這是一段來自戰國策的歷史敘述，記載了當時各國君臣之間的政治對話與外交策略。具體描述了相關人物在面對國家危機或戰略抉擇時的應對之策（段落編號：2）。","analysis":"【主題與背景】\\\\n本段落（2）反映了戰國時期諸侯國之間錯綜複雜的政治角力與軍事衝突。當時各國為了爭奪霸權或尋求生存，頻繁展開外交周旋與軍事行動。\\\\n\\\\n【詞義與名物】\\\\n「君臣」：指各國的統治者與輔佐之臣。\\\\n「戰國」：時代背景，羣雄並起。\\\\n\\\\n【縱橫機謋】\\\\n段落中展現了典型的戰國策士風範。他們善於揣摩人心，分析利害關係，並利用各國之間的矛盾與利益衝突，提出巧言善辯的策略，以達到保全自身或削弱敵國的政治目的。"}},{"id":"zhan-guo-ce_ch-1_p-5","chapterId":"zhan-guo-ce_ch-1","order":5,"canonicalText":"東周與西周爭，西周欲和於楚、韓。齊明謂東周君曰：「臣恐西周之與楚、韓寶，令之為己求地於東周也。不如謂楚、韓曰：『西周之欲入寶，持二端。今東周之兵不急西周，西周之寶不入楚、韓。』楚、韓欲得寶，即且趣我攻西周。西周寶出，是我為楚、韓取寶以德之也，西周弱矣。」","sentenceIds":["zhan-guo-ce_ch-1_p-5_s-1","zhan-guo-ce_ch-1_p-5_s-2","zhan-guo-ce_ch-1_p-5_s-3","zhan-guo-ce_ch-1_p-5_s-4","zhan-guo-ce_ch-1_p-5_s-5","zhan-guo-ce_ch-1_p-5_s-6","zhan-guo-ce_ch-1_p-5_s-7"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/zhan-guo-ce/zh"}],"readingAid":{"translation":"這是一段來自戰國策的歷史敘述，記載了當時各國君臣之間的政治對話與外交策略。具體描述了相關人物在面對國家危機或戰略抉擇時的應對之策（段落編號：3）。","analysis":"【主題與背景】\\\\n本段落（3）反映了戰國時期諸侯國之間錯綜複雜的政治角力與軍事衝突。當時各國為了爭奪霸權或尋求生存，頻繁展開外交周旋與軍事行動。\\\\n\\\\n【詞義與名物】\\\\n「君臣」：指各國的統治者與輔佐之臣。\\\\n「戰國」：時代背景，羣雄並起。\\\\n\\\\n【縱橫機謋】\\\\n段落中展現了典型的戰國策士風範。他們善於揣摩人心，分析利害關係，並利用各國之間的矛盾與利益衝突，提出巧言善辯的策略，以達到保全自身或削弱敵國的政治目的。"}},{"id":"zhan-guo-ce_ch-1_p-6","chapterId":"zhan-guo-ce_ch-1","order":6,"canonicalText":"東周欲為稻，西周不下水，東周患之。蘇子謂東周君曰：「臣請使西周下水可乎？」乃往見西周之君曰：「君之謀過矣！今不下水，所以富東周也。今其民皆種麥，無他種矣。君若欲害之，不若一為下水，以病其所種。下水，東周必復種稻；種稻而復奪之。若是，則東周之民可令一仰西周，而受命於君矣。」西周君曰：「善。」遂下水。蘇子亦得兩國之金也。","sentenceIds":["zhan-guo-ce_ch-1_p-6_s-1","zhan-guo-ce_ch-1_p-6_s-2","zhan-guo-ce_ch-1_p-6_s-3","zhan-guo-ce_ch-1_p-6_s-4","zhan-guo-ce_ch-1_p-6_s-5","zhan-guo-ce_ch-1_p-6_s-6","zhan-guo-ce_ch-1_p-6_s-7","zhan-guo-ce_ch-1_p-6_s-8","zhan-guo-ce_ch-1_p-6_s-9","zhan-guo-ce_ch-1_p-6_s-10","zhan-guo-ce_ch-1_p-6_s-11","zhan-guo-ce_ch-1_p-6_s-12"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/zhan-guo-ce/zh"}],"readingAid":{"translation":"這是一段來自戰國策的歷史敘述，記載了當時各國君臣之間的政治對話與外交策略。具體描述了相關人物在面對國家危機或戰略抉擇時的應對之策（段落編號：4）。","analysis":"【主題與背景】\\\\n本段落（4）反映了戰國時期諸侯國之間錯綜複雜的政治角力與軍事衝突。當時各國為了爭奪霸權或尋求生存，頻繁展開外交周旋與軍事行動。\\\\n\\\\n【詞義與名物】\\\\n「君臣」：指各國的統治者與輔佐之臣。\\\\n「戰國」：時代背景，羣雄並起。\\\\n\\\\n【縱橫機謋】\\\\n段落中展現了典型的戰國策士風範。他們善於揣摩人心，分析利害關係，並利用各國之間的矛盾與利益衝突，提出巧言善辯的策略，以達到保全自身或削弱敵國的政治目的。"}},{"id":"zhan-guo-ce_ch-1_p-7","chapterId":"zhan-guo-ce_ch-1","order":7,"canonicalText":"昭獻在陽翟，周君將令相國往，相國將不欲。蘇厲為之謂周君曰：「楚王與魏王遇也，主君令陳封之楚，令向公之魏；楚、韓之遇也，主君令許公之楚，令向公之韓。今昭獻非人主也，而主君令相國往，若其王在陽翟，主君將令誰往？」周君曰：「善。」乃止其行。","sentenceIds":["zhan-guo-ce_ch-1_p-7_s-1","zhan-guo-ce_ch-1_p-7_s-2","zhan-guo-ce_ch-1_p-7_s-3","zhan-guo-ce_ch-1_p-7_s-4","zhan-guo-ce_ch-1_p-7_s-5","zhan-guo-ce_ch-1_p-7_s-6"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/zhan-guo-ce/zh"}],"readingAid":{"translation":"這是一段來自戰國策的歷史敘述，記載了當時各國君臣之間的政治對話與外交策略。具體描述了相關人物在面對國家危機或戰略抉擇時的應對之策（段落編號：5）。","analysis":"【主題與背景】\\\\n本段落（5）反映了戰國時期諸侯國之間錯綜複雜的政治角力與軍事衝突。當時各國為了爭奪霸權或尋求生存，頻繁展開外交周旋與軍事行動。\\\\n\\\\n【詞義與名物】\\\\n「君臣」：指各國的統治者與輔佐之臣。\\\\n「戰國」：時代背景，羣雄並起。\\\\n\\\\n【縱橫機謋】\\\\n段落中展現了典型的戰國策士風範。他們善於揣摩人心，分析利害關係，並利用各國之間的矛盾與利益衝突，提出巧言善辯的策略，以達到保全自身或削弱敵國的政治目的。"}},{"id":"zhan-guo-ce_ch-1_p-8","chapterId":"zhan-guo-ce_ch-1","order":8,"canonicalText":"秦假道於周以伐韓，周恐假之而惡於韓，不假而惡於秦。史黶謂周君曰：「君何不令人謂韓公叔曰：『秦敢絕塞而伐韓者，信東周也。公何不與周地，發重使使之楚，秦必疑，不信周，是韓不伐也。』又謂秦王曰：『韓強與周地，將以疑周於秦，寡人不敢弗受。』秦必無辭而令周弗受，是得地於韓而聽於秦也。」","sentenceIds":["zhan-guo-ce_ch-1_p-8_s-1","zhan-guo-ce_ch-1_p-8_s-2","zhan-guo-ce_ch-1_p-8_s-3","zhan-guo-ce_ch-1_p-8_s-4","zhan-guo-ce_ch-1_p-8_s-5","zhan-guo-ce_ch-1_p-8_s-6"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/zhan-guo-ce/zh"}],"readingAid":{"translation":"這是一段來自戰國策的歷史敘述，記載了當時各國君臣之間的政治對話與外交策略。具體描述了相關人物在面對國家危機或戰略抉擇時的應對之策（段落編號：6）。","analysis":"【主題與背景】\\\\n本段落（6）反映了戰國時期諸侯國之間錯綜複雜的政治角力與軍事衝突。當時各國為了爭奪霸權或尋求生存，頻繁展開外交周旋與軍事行動。\\\\n\\\\n【詞義與名物】\\\\n「君臣」：指各國的統治者與輔佐之臣。\\\\n「戰國」：時代背景，羣雄並起。\\\\n\\\\n【縱橫機謋】\\\\n段落中展現了典型的戰國策士風範。他們善於揣摩人心，分析利害關係，並利用各國之間的矛盾與利益衝突，提出巧言善辯的策略，以達到保全自身或削弱敵國的政治目的。"}},{"id":"zhan-guo-ce_ch-1_p-9","chapterId":"zhan-guo-ce_ch-1","order":9,"canonicalText":"楚攻雍氏，周餦秦、韓，楚王怒周，周之君患之。為周謂楚王曰：「以王之強而怒周，周恐，必以國合於所與粟之國，則是勁王之敵也。故王不如速解周恐，彼前得罪而後得解，必厚事王矣。」","sentenceIds":["zhan-guo-ce_ch-1_p-9_s-1","zhan-guo-ce_ch-1_p-9_s-2","zhan-guo-ce_ch-1_p-9_s-3","zhan-guo-ce_ch-1_p-9_s-4"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/zhan-guo-ce/zh"}],"readingAid":{"translation":"這是一段來自戰國策的歷史敘述，記載了當時各國君臣之間的政治對話與外交策略。具體描述了相關人物在面對國家危機或戰略抉擇時的應對之策（段落編號：7）。","analysis":"【主題與背景】\\\\n本段落（7）反映了戰國時期諸侯國之間錯綜複雜的政治角力與軍事衝突。當時各國為了爭奪霸權或尋求生存，頻繁展開外交周旋與軍事行動。\\\\n\\\\n【詞義與名物】\\\\n「君臣」：指各國的統治者與輔佐之臣。\\\\n「戰國」：時代背景，羣雄並起。\\\\n\\\\n【縱橫機謋】\\\\n段落中展現了典型的戰國策士風範。他們善於揣摩人心，分析利害關係，並利用各國之間的矛盾與利益衝突，提出巧言善辯的策略，以達到保全自身或削弱敵國的政治目的。"}},{"id":"zhan-guo-ce_ch-1_p-10","chapterId":"zhan-guo-ce_ch-1","order":10,"canonicalText":"周最謂石禮曰：「子何不以秦攻齊？臣請令齊相子，子以齊事秦，必無處矣。子因令周最居魏以共之，是天下制於子也。子東重於齊，西貴於秦，秦、齊合，則子常重矣。」","sentenceIds":["zhan-guo-ce_ch-1_p-10_s-1","zhan-guo-ce_ch-1_p-10_s-2","zhan-guo-ce_ch-1_p-10_s-3","zhan-guo-ce_ch-1_p-10_s-4","zhan-guo-ce_ch-1_p-10_s-5"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/zhan-guo-ce/zh"}],"readingAid":{"translation":"這是一段來自戰國策的歷史敘述，記載了當時各國君臣之間的政治對話與外交策略。具體描述了相關人物在面對國家危機或戰略抉擇時的應對之策（段落編號：8）。","analysis":"【主題與背景】\\\\n本段落（8）反映了戰國時期諸侯國之間錯綜複雜的政治角力與軍事衝突。當時各國為了爭奪霸權或尋求生存，頻繁展開外交周旋與軍事行動。\\\\n\\\\n【詞義與名物】\\\\n「君臣」：指各國的統治者與輔佐之臣。\\\\n「戰國」：時代背景，羣雄並起。\\\\n\\\\n【縱橫機謋】\\\\n段落中展現了典型的戰國策士風範。他們善於揣摩人心，分析利害關係，並利用各國之間的矛盾與利益衝突，提出巧言善辯的策略，以達到保全自身或削弱敵國的政治目的。"}},{"id":"zhan-guo-ce_ch-1_p-11","chapterId":"zhan-guo-ce_ch-1","order":11,"canonicalText":"周相呂倉見客於周君。前相工師籍恐客之傷己也，因令人謂周君曰：「客者，辯士也，然而所以不可者，好毀人。」","sentenceIds":["zhan-guo-ce_ch-1_p-11_s-1","zhan-guo-ce_ch-1_p-11_s-2","zhan-guo-ce_ch-1_p-11_s-3"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/zhan-guo-ce/zh"}],"readingAid":{"translation":"這是一段來自戰國策的歷史敘述，記載了當時各國君臣之間的政治對話與外交策略。具體描述了相關人物在面對國家危機或戰略抉擇時的應對之策（段落編號：9）。","analysis":"【主題與背景】\\\\n本段落（9）反映了戰國時期諸侯國之間錯綜複雜的政治角力與軍事衝突。當時各國為了爭奪霸權或尋求生存，頻繁展開外交周旋與軍事行動。\\\\n\\\\n【詞義與名物】\\\\n「君臣」：指各國的統治者與輔佐之臣。\\\\n「戰國」：時代背景，羣雄並起。\\\\n\\\\n【縱橫機謋】\\\\n段落中展現了典型的戰國策士風範。他們善於揣摩人心，分析利害關係，並利用各國之間的矛盾與利益衝突，提出巧言善辯的策略，以達到保全自身或削弱敵國的政治目的。"}},{"id":"zhan-guo-ce_ch-1_p-12","chapterId":"zhan-guo-ce_ch-1","order":12,"canonicalText":"周文君免士工師籍，相呂倉，國人不說也。君有閔閔之心。謂周文君曰：「國必有誹譽，忠臣令誹在己，譽在上。宋君奪民時以為臺，而非民之，無忠臣以掩蓋之也，子罕釋相為司空，民非子罕而善其君；齊桓公宮中七市，女閭七百，國人非之，管仲故為三歸之家，以掩桓公，非自傷於民也。《春秋》記臣弒君者以百數，皆大臣見譽者也。故大臣得譽，非國家之美也。故眾庶成彊，增積成山。」周君遂不免。","sentenceIds":["zhan-guo-ce_ch-1_p-12_s-1","zhan-guo-ce_ch-1_p-12_s-2","zhan-guo-ce_ch-1_p-12_s-3","zhan-guo-ce_ch-1_p-12_s-4","zhan-guo-ce_ch-1_p-12_s-5","zhan-guo-ce_ch-1_p-12_s-6","zhan-guo-ce_ch-1_p-12_s-7","zhan-guo-ce_ch-1_p-12_s-8","zhan-guo-ce_ch-1_p-12_s-9"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/zhan-guo-ce/zh"}],"readingAid":{"translation":"這是一段來自戰國策的歷史敘述，記載了當時各國君臣之間的政治對話與外交策略。具體描述了相關人物在面對國家危機或戰略抉擇時的應對之策（段落編號：10）。","analysis":"【主題與背景】\\\\n本段落（10）反映了戰國時期諸侯國之間錯綜複雜的政治角力與軍事衝突。當時各國為了爭奪霸權或尋求生存，頻繁展開外交周旋與軍事行動。\\\\n\\\\n【詞義與名物】\\\\n「君臣」：指各國的統治者與輔佐之臣。\\\\n「戰國」：時代背景，羣雄並起。\\\\n\\\\n【縱橫機謋】\\\\n段落中展現了典型的戰國策士風範。他們善於揣摩人心，分析利害關係，並利用各國之間的矛盾與利益衝突，提出巧言善辯的策略，以達到保全自身或削弱敵國的政治目的。"}},{"id":"zhan-guo-ce_ch-1_p-13","chapterId":"zhan-guo-ce_ch-1","order":13,"canonicalText":"溫人之周，周不納。「客即？」對曰：「主人也。」問其巷而不知也，使因囚之。君使人問之曰：「子非周人，而自謂非客何也？」對曰：「臣少而誦《》，《》曰：『普天之下，莫非王土；率土之濱，莫非王臣。』今周君天下，則我天子之臣，而又為客哉？故曰主人。」君乃使吏出之。","sentenceIds":["zhan-guo-ce_ch-1_p-13_s-1","zhan-guo-ce_ch-1_p-13_s-2","zhan-guo-ce_ch-1_p-13_s-3","zhan-guo-ce_ch-1_p-13_s-4","zhan-guo-ce_ch-1_p-13_s-5","zhan-guo-ce_ch-1_p-13_s-6","zhan-guo-ce_ch-1_p-13_s-7","zhan-guo-ce_ch-1_p-13_s-8","zhan-guo-ce_ch-1_p-13_s-9","zhan-guo-ce_ch-1_p-13_s-10"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/zhan-guo-ce/zh"}],"readingAid":{"translation":"這是一段來自戰國策的歷史敘述，記載了當時各國君臣之間的政治對話與外交策略。具體描述了相關人物在面對國家危機或戰略抉擇時的應對之策（段落編號：11）。","analysis":"【主題與背景】\\\\n本段落（11）反映了戰國時期諸侯國之間錯綜複雜的政治角力與軍事衝突。當時各國為了爭奪霸權或尋求生存，頻繁展開外交周旋與軍事行動。\\\\n\\\\n【詞義與名物】\\\\n「君臣」：指各國的統治者與輔佐之臣。\\\\n「戰國」：時代背景，羣雄並起。\\\\n\\\\n【縱橫機謋】\\\\n段落中展現了典型的戰國策士風範。他們善於揣摩人心，分析利害關係，並利用各國之間的矛盾與利益衝突，提出巧言善辯的策略，以達到保全自身或削弱敵國的政治目的。"}},{"id":"zhan-guo-ce_ch-1_p-14","chapterId":"zhan-guo-ce_ch-1","order":14,"canonicalText":"或為周最謂金投曰：「秦以周最之齊疑天下，而又知趙之難子齊人戰，恐齊、韓之合，必先合於秦。秦、齊合，則公之國虛矣。公不如救齊，因佐秦而伐韓、魏，上黨、長子趙之有。公東收寶於秦，南取地於韓，魏因以因，徐為之東，則有合矣。」","sentenceIds":["zhan-guo-ce_ch-1_p-14_s-1","zhan-guo-ce_ch-1_p-14_s-2","zhan-guo-ce_ch-1_p-14_s-3","zhan-guo-ce_ch-1_p-14_s-4","zhan-guo-ce_ch-1_p-14_s-5"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/zhan-guo-ce/zh"}],"readingAid":{"translation":"這是一段來自戰國策的歷史敘述，記載了當時各國君臣之間的政治對話與外交策略。具體描述了相關人物在面對國家危機或戰略抉擇時的應對之策（段落編號：12）。","analysis":"【主題與背景】\\\\n本段落（12）反映了戰國時期諸侯國之間錯綜複雜的政治角力與軍事衝突。當時各國為了爭奪霸權或尋求生存，頻繁展開外交周旋與軍事行動。\\\\n\\\\n【詞義與名物】\\\\n「君臣」：指各國的統治者與輔佐之臣。\\\\n「戰國」：時代背景，羣雄並起。\\\\n\\\\n【縱橫機謋】\\\\n段落中展現了典型的戰國策士風範。他們善於揣摩人心，分析利害關係，並利用各國之間的矛盾與利益衝突，提出巧言善辯的策略，以達到保全自身或削弱敵國的政治目的。"}},{"id":"zhan-guo-ce_ch-1_p-15","chapterId":"zhan-guo-ce_ch-1","order":15,"canonicalText":"周最謂金投曰：「公負令秦與強齊戰。戰勝，秦且收齊而封之，使無多割，而聽天下之戰；不勝，國大傷，不得不聽秦。秦盡韓、魏之上黨、太原，西止秦之有已。秦地，天下之半也，制齊、楚、三晉之命，復國且身危，是何計之道也。」","sentenceIds":["zhan-guo-ce_ch-1_p-15_s-1","zhan-guo-ce_ch-1_p-15_s-2","zhan-guo-ce_ch-1_p-15_s-3","zhan-guo-ce_ch-1_p-15_s-4","zhan-guo-ce_ch-1_p-15_s-5","zhan-guo-ce_ch-1_p-15_s-6"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/zhan-guo-ce/zh"}],"readingAid":{"translation":"這是一段來自戰國策的歷史敘述，記載了當時各國君臣之間的政治對話與外交策略。具體描述了相關人物在面對國家危機或戰略抉擇時的應對之策（段落編號：13）。","analysis":"【主題與背景】\\\\n本段落（13）反映了戰國時期諸侯國之間錯綜複雜的政治角力與軍事衝突。當時各國為了爭奪霸權或尋求生存，頻繁展開外交周旋與軍事行動。\\\\n\\\\n【詞義與名物】\\\\n「君臣」：指各國的統治者與輔佐之臣。\\\\n「戰國」：時代背景，羣雄並起。\\\\n\\\\n【縱橫機謋】\\\\n段落中展現了典型的戰國策士風範。他們善於揣摩人心，分析利害關係，並利用各國之間的矛盾與利益衝突，提出巧言善辯的策略，以達到保全自身或削弱敵國的政治目的。"}},{"id":"zhan-guo-ce_ch-1_p-16","chapterId":"zhan-guo-ce_ch-1","order":16,"canonicalText":"石行秦謂大梁造曰：「欲決霸王之名，不如備兩周辯知之士。」謂周君曰：「君不如令辯知之士，為君爭於秦。」","sentenceIds":["zhan-guo-ce_ch-1_p-16_s-1","zhan-guo-ce_ch-1_p-16_s-2","zhan-guo-ce_ch-1_p-16_s-3"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/zhan-guo-ce/zh"}],"readingAid":{"translation":"本段典籍核心大意在於闡述現代維度的價值理念。具體而言，文言語意涵蓋了有關講述、統治者、講述、統治者、統治者的深層觀點，揭示了事物運作與組織管理之法則。全段旨在提醒人們在處世與決策時應保持清醒的洞察力。〔《戰國策》〈東周〉第16節導讀〕","analysis":"【主旨】本段聚焦於《戰國策》的核心議題，解析了當前章節的精髓與核心觀念。\\n【關鍵詞義】「石」──古漢語核心意象與經典表達；「行」──古漢語核心意象與經典表達；「秦」──古漢語核心意象與經典表達；「謂」──古漢語核心意象與經典表達\\n【思想脈絡】段落結構嚴謹，語意層次分明。從「石」出發，漸次遞進至全篇哲理宏旨。\\n【當代啟示】提示現代人在面對複雜情境時，應汲取古代智慧，保持理性與定力。"}},{"id":"zhan-guo-ce_ch-1_p-17","chapterId":"zhan-guo-ce_ch-1","order":17,"canonicalText":"謂薛公曰：「周最於齊王也而逐之，聽祝弗，相呂禮者，欲取秦。秦、齊合，弗與禮重矣。有周齊，秦必輕君。君弗如急北兵，趨趙以秦、魏，收周最以為後行，且反齊王之信，又禁天下之率。齊無秦，天下果，弗必走，齊王誰與為其國？」","sentenceIds":["zhan-guo-ce_ch-1_p-17_s-1","zhan-guo-ce_ch-1_p-17_s-2","zhan-guo-ce_ch-1_p-17_s-3","zhan-guo-ce_ch-1_p-17_s-4","zhan-guo-ce_ch-1_p-17_s-5","zhan-guo-ce_ch-1_p-17_s-6"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/zhan-guo-ce/zh"}],"readingAid":{"translation":"這是一段來自戰國策的歷史敘述，記載了當時各國君臣之間的政治對話與外交策略。具體描述了相關人物在面對國家危機或戰略抉擇時的應對之策（段落編號：14）。","analysis":"【主題與背景】\\\\n本段落（14）反映了戰國時期諸侯國之間錯綜複雜的政治角力與軍事衝突。當時各國為了爭奪霸權或尋求生存，頻繁展開外交周旋與軍事行動。\\\\n\\\\n【詞義與名物】\\\\n「君臣」：指各國的統治者與輔佐之臣。\\\\n「戰國」：時代背景，羣雄並起。\\\\n\\\\n【縱橫機謋】\\\\n段落中展現了典型的戰國策士風範。他們善於揣摩人心，分析利害關係，並利用各國之間的矛盾與利益衝突，提出巧言善辯的策略，以達到保全自身或削弱敵國的政治目的。"}},{"id":"zhan-guo-ce_ch-1_p-18","chapterId":"zhan-guo-ce_ch-1","order":18,"canonicalText":"齊聽祝弗，外周最。謂齊王曰：「逐周最、聽祝弗、相呂禮者，欲深取秦也。秦得天下，則伐齊深矣。夫齊合，則趙恐伐，故急兵以示秦。秦以趙攻，與之齊伐趙，其實同理，必不處矣。故用祝弗，即天下之理也。」","sentenceIds":["zhan-guo-ce_ch-1_p-18_s-1","zhan-guo-ce_ch-1_p-18_s-2","zhan-guo-ce_ch-1_p-18_s-3","zhan-guo-ce_ch-1_p-18_s-4","zhan-guo-ce_ch-1_p-18_s-5","zhan-guo-ce_ch-1_p-18_s-6","zhan-guo-ce_ch-1_p-18_s-7"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/zhan-guo-ce/zh"}],"readingAid":{"translation":"這是一段來自戰國策的歷史敘述，記載了當時各國君臣之間的政治對話與外交策略。具體描述了相關人物在面對國家危機或戰略抉擇時的應對之策（段落編號：15）。","analysis":"【主題與背景】\\\\n本段落（15）反映了戰國時期諸侯國之間錯綜複雜的政治角力與軍事衝突。當時各國為了爭奪霸權或尋求生存，頻繁展開外交周旋與軍事行動。\\\\n\\\\n【詞義與名物】\\\\n「君臣」：指各國的統治者與輔佐之臣。\\\\n「戰國」：時代背景，羣雄並起。\\\\n\\\\n【縱橫機謋】\\\\n段落中展現了典型的戰國策士風範。他們善於揣摩人心，分析利害關係，並利用各國之間的矛盾與利益衝突，提出巧言善辯的策略，以達到保全自身或削弱敵國的政治目的。"}},{"id":"zhan-guo-ce_ch-1_p-19","chapterId":"zhan-guo-ce_ch-1","order":19,"canonicalText":"蘇厲為周最謂蘇秦曰：「君不如令王聽最，以地合於魏，趙故必怒，合於齊，是君以合齊與強楚。吏產子君，若欲因最之事，則合齊者，君也；割地者，最也。」","sentenceIds":["zhan-guo-ce_ch-1_p-19_s-1","zhan-guo-ce_ch-1_p-19_s-2","zhan-guo-ce_ch-1_p-19_s-3","zhan-guo-ce_ch-1_p-19_s-4"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/zhan-guo-ce/zh"}],"readingAid":{"translation":"這是一段來自戰國策的歷史敘述，記載了當時各國君臣之間的政治對話與外交策略。具體描述了相關人物在面對國家危機或戰略抉擇時的應對之策（段落編號：16）。","analysis":"【主題與背景】\\\\n本段落（16）反映了戰國時期諸侯國之間錯綜複雜的政治角力與軍事衝突。當時各國為了爭奪霸權或尋求生存，頻繁展開外交周旋與軍事行動。\\\\n\\\\n【詞義與名物】\\\\n「君臣」：指各國的統治者與輔佐之臣。\\\\n「戰國」：時代背景，羣雄並起。\\\\n\\\\n【縱橫機謋】\\\\n段落中展現了典型的戰國策士風範。他們善於揣摩人心，分析利害關係，並利用各國之間的矛盾與利益衝突，提出巧言善辯的策略，以達到保全自身或削弱敵國的政治目的。"}},{"id":"zhan-guo-ce_ch-1_p-20","chapterId":"zhan-guo-ce_ch-1","order":20,"canonicalText":"謂周最曰：「仇赫之相宋，將以觀秦之應趙、宋，敗三國。三國不敗，將興趙、宋合於東方以孤秦。亦將觀韓、魏之於秦也，不固，則將與宋敗三國；則賣趙、宋於三國。公何不令人謂韓、魏之王曰：『欲秦、趙之相賣乎？何不合周最兼相，視之不可離，則秦、趙必相賣以合於王也。』」","sentenceIds":["zhan-guo-ce_ch-1_p-20_s-1","zhan-guo-ce_ch-1_p-20_s-2","zhan-guo-ce_ch-1_p-20_s-3","zhan-guo-ce_ch-1_p-20_s-4","zhan-guo-ce_ch-1_p-20_s-5","zhan-guo-ce_ch-1_p-20_s-6","zhan-guo-ce_ch-1_p-20_s-7"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/zhan-guo-ce/zh"}],"readingAid":{"translation":"這是一段來自戰國策的歷史敘述，記載了當時各國君臣之間的政治對話與外交策略。具體描述了相關人物在面對國家危機或戰略抉擇時的應對之策（段落編號：17）。","analysis":"【主題與背景】\\\\n本段落（17）反映了戰國時期諸侯國之間錯綜複雜的政治角力與軍事衝突。當時各國為了爭奪霸權或尋求生存，頻繁展開外交周旋與軍事行動。\\\\n\\\\n【詞義與名物】\\\\n「君臣」：指各國的統治者與輔佐之臣。\\\\n「戰國」：時代背景，羣雄並起。\\\\n\\\\n【縱橫機謋】\\\\n段落中展現了典型的戰國策士風範。他們善於揣摩人心，分析利害關係，並利用各國之間的矛盾與利益衝突，提出巧言善辯的策略，以達到保全自身或削弱敵國的政治目的。"}},{"id":"zhan-guo-ce_ch-1_p-21","chapterId":"zhan-guo-ce_ch-1","order":21,"canonicalText":"為周最謂魏王曰：「秦知趙之難與齊戰也，將恐齊、趙之合也，必陰勁之。趙不敢戰，恐秦不己收也，先合於齊。秦、趙爭齊，而王無人焉，不可。王不去周最，合與收齊，而以兵之急則伐齊，無因事也。」","sentenceIds":["zhan-guo-ce_ch-1_p-21_s-1","zhan-guo-ce_ch-1_p-21_s-2","zhan-guo-ce_ch-1_p-21_s-3","zhan-guo-ce_ch-1_p-21_s-4","zhan-guo-ce_ch-1_p-21_s-5"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/zhan-guo-ce/zh"}],"readingAid":{"translation":"這是一段來自戰國策的歷史敘述，記載了當時各國君臣之間的政治對話與外交策略。具體描述了相關人物在面對國家危機或戰略抉擇時的應對之策（段落編號：18）。","analysis":"【主題與背景】\\\\n本段落（18）反映了戰國時期諸侯國之間錯綜複雜的政治角力與軍事衝突。當時各國為了爭奪霸權或尋求生存，頻繁展開外交周旋與軍事行動。\\\\n\\\\n【詞義與名物】\\\\n「君臣」：指各國的統治者與輔佐之臣。\\\\n「戰國」：時代背景，羣雄並起。\\\\n\\\\n【縱橫機謋】\\\\n段落中展現了典型的戰國策士風範。他們善於揣摩人心，分析利害關係，並利用各國之間的矛盾與利益衝突，提出巧言善辯的策略，以達到保全自身或削弱敵國的政治目的。"}},{"id":"zhan-guo-ce_ch-1_p-22","chapterId":"zhan-guo-ce_ch-1","order":22,"canonicalText":"謂周最曰：「魏王以國與先生，貴合於秦以伐齊。薛公故主，輕忘其薛，不顧其先君之丘墓，而公獨脩虛信，為茂行，明群臣，據故主，不與伐齊者產，以忿強秦，不可。公不如謂魏王、薛公曰：『請為王入齊，天下不能傷齊。而有變，臣請為救之；無變，王遂伐之。且臣為齊奴也，如累王之交於天下，不可。王為臣賜厚矣，臣入齊，則王亦無齊之累也。』」","sentenceIds":["zhan-guo-ce_ch-1_p-22_s-1","zhan-guo-ce_ch-1_p-22_s-2","zhan-guo-ce_ch-1_p-22_s-3","zhan-guo-ce_ch-1_p-22_s-4","zhan-guo-ce_ch-1_p-22_s-5","zhan-guo-ce_ch-1_p-22_s-6","zhan-guo-ce_ch-1_p-22_s-7","zhan-guo-ce_ch-1_p-22_s-8"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/zhan-guo-ce/zh"}],"readingAid":{"translation":"這是一段來自戰國策的歷史敘述，記載了當時各國君臣之間的政治對話與外交策略。具體描述了相關人物在面對國家危機或戰略抉擇時的應對之策（段落編號：19）。","analysis":"【主題與背景】\\\\n本段落（19）反映了戰國時期諸侯國之間錯綜複雜的政治角力與軍事衝突。當時各國為了爭奪霸權或尋求生存，頻繁展開外交周旋與軍事行動。\\\\n\\\\n【詞義與名物】\\\\n「君臣」：指各國的統治者與輔佐之臣。\\\\n「戰國」：時代背景，羣雄並起。\\\\n\\\\n【縱橫機謋】\\\\n段落中展現了典型的戰國策士風範。他們善於揣摩人心，分析利害關係，並利用各國之間的矛盾與利益衝突，提出巧言善辯的策略，以達到保全自身或削弱敵國的政治目的。"}},{"id":"zhan-guo-ce_ch-1_p-23","chapterId":"zhan-guo-ce_ch-1","order":23,"canonicalText":"趙取周之祭地，周君患之，告於鄭朝。鄭朝曰：「君無患也，臣請以三十金復取之。」周君予之，鄭朝獻之趙太卜，因告以祭地事。及王病，使卜之。太卜譴之曰：「周之祭地為祟。」趙乃還之。","sentenceIds":["zhan-guo-ce_ch-1_p-23_s-1","zhan-guo-ce_ch-1_p-23_s-2","zhan-guo-ce_ch-1_p-23_s-3","zhan-guo-ce_ch-1_p-23_s-4","zhan-guo-ce_ch-1_p-23_s-5","zhan-guo-ce_ch-1_p-23_s-6"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/zhan-guo-ce/zh"}],"readingAid":{"translation":"這是一段來自戰國策的歷史敘述，記載了當時各國君臣之間的政治對話與外交策略。具體描述了相關人物在面對國家危機或戰略抉擇時的應對之策（段落編號：20）。","analysis":"【主題與背景】\\\\n本段落（20）反映了戰國時期諸侯國之間錯綜複雜的政治角力與軍事衝突。當時各國為了爭奪霸權或尋求生存，頻繁展開外交周旋與軍事行動。\\\\n\\\\n【詞義與名物】\\\\n「君臣」：指各國的統治者與輔佐之臣。\\\\n「戰國」：時代背景，羣雄並起。\\\\n\\\\n【縱橫機謋】\\\\n段落中展現了典型的戰國策士風範。他們善於揣摩人心，分析利害關係，並利用各國之間的矛盾與利益衝突，提出巧言善辯的策略，以達到保全自身或削弱敵國的政治目的。"}},{"id":"zhan-guo-ce_ch-1_p-24","chapterId":"zhan-guo-ce_ch-1","order":24,"canonicalText":"杜赫欲重景翠於周，謂周君曰：「君之國小，盡君子重寶珠玉以事諸侯，不可不察也。譬之如張羅者，張於無鳥之所，則終日無所得矣；張於多鳥處，則又駭鳥矣；必須張於有鳥無鳥之際，然後能多得鳥矣。今君將施於大人，大人輕君；施與小人，小人無可以求，又費財焉。君必施於今之窮士，不必且為大人者，故能得欲矣。」","sentenceIds":["zhan-guo-ce_ch-1_p-24_s-1","zhan-guo-ce_ch-1_p-24_s-2","zhan-guo-ce_ch-1_p-24_s-3","zhan-guo-ce_ch-1_p-24_s-4","zhan-guo-ce_ch-1_p-24_s-5","zhan-guo-ce_ch-1_p-24_s-6","zhan-guo-ce_ch-1_p-24_s-7","zhan-guo-ce_ch-1_p-24_s-8"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/zhan-guo-ce/zh"}],"readingAid":{"translation":"這是一段來自戰國策的歷史敘述，記載了當時各國君臣之間的政治對話與外交策略。具體描述了相關人物在面對國家危機或戰略抉擇時的應對之策（段落編號：21）。","analysis":"【主題與背景】\\\\n本段落（21）反映了戰國時期諸侯國之間錯綜複雜的政治角力與軍事衝突。當時各國為了爭奪霸權或尋求生存，頻繁展開外交周旋與軍事行動。\\\\n\\\\n【詞義與名物】\\\\n「君臣」：指各國的統治者與輔佐之臣。\\\\n「戰國」：時代背景，羣雄並起。\\\\n\\\\n【縱橫機謋】\\\\n段落中展現了典型的戰國策士風範。他們善於揣摩人心，分析利害關係，並利用各國之間的矛盾與利益衝突，提出巧言善辯的策略，以達到保全自身或削弱敵國的政治目的。"}},{"id":"zhan-guo-ce_ch-1_p-25","chapterId":"zhan-guo-ce_ch-1","order":25,"canonicalText":"周共太子死，有五庶子，皆愛之，而無適立也。司馬翦謂楚王曰：「何不封公子咎，而為之請太子？」左成謂司馬翦曰：「周君不聽，是公之知困而交絕於周也。不如謂周君曰：『孰欲立也？微告翦，翦今楚王資之以地。』公若欲為太子，因令人謂相國御展子，廧夫空曰：『王類欲令若為之。』此健士也，居中不便於相國。」相國令之為太子。","sentenceIds":["zhan-guo-ce_ch-1_p-25_s-1","zhan-guo-ce_ch-1_p-25_s-2","zhan-guo-ce_ch-1_p-25_s-3","zhan-guo-ce_ch-1_p-25_s-4","zhan-guo-ce_ch-1_p-25_s-5","zhan-guo-ce_ch-1_p-25_s-6","zhan-guo-ce_ch-1_p-25_s-7","zhan-guo-ce_ch-1_p-25_s-8"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/zhan-guo-ce/zh"}],"readingAid":{"translation":"《戰國策・東周》史實記載：「周共太子死，有五庶子，皆愛之，而無適立也。司馬翦謂楚王曰：何不封公子……」。本段記述歷史風雲人物事跡、朝代興衰成敗與國家政治外交謀略。","analysis":"【主題與背景】本段選自史學名著《戰國策・東周》。記載重要歷史事件與君臣對答紀實。\\\\n【詞義與名物】經文核心：「周共太子死，有五庶子」，展現古代制度、官制與史學史料價值。\\\\n【史學評價】史筆客觀嚴謹，為後世提供了珍貴的歷史經驗與治國借鑑。"}},{"id":"zhan-guo-ce_ch-1_p-26","chapterId":"zhan-guo-ce_ch-1","order":26,"canonicalText":"三國隘秦，周令其相之秦，以秦之輕也，留其行。有人謂相國曰：「秦之輕重，未可知也。秦欲知三國之情，公不如遂見秦王曰：『請謂王聽東方之處。』秦必重公。是公重周，重周以取秦也。齊重故有周，而已取秦。是周常不失重國之交也。」","sentenceIds":["zhan-guo-ce_ch-1_p-26_s-1","zhan-guo-ce_ch-1_p-26_s-2","zhan-guo-ce_ch-1_p-26_s-3","zhan-guo-ce_ch-1_p-26_s-4","zhan-guo-ce_ch-1_p-26_s-5","zhan-guo-ce_ch-1_p-26_s-6","zhan-guo-ce_ch-1_p-26_s-7","zhan-guo-ce_ch-1_p-26_s-8"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/zhan-guo-ce/zh"}],"readingAid":{"translation":"這是一段來自戰國策的歷史敘述，記載了當時各國君臣之間的政治對話與外交策略。具體描述了相關人物在面對國家危機或戰略抉擇時的應對之策（段落編號：22）。","analysis":"【主題與背景】\\\\n本段落（22）反映了戰國時期諸侯國之間錯綜複雜的政治角力與軍事衝突。當時各國為了爭奪霸權或尋求生存，頻繁展開外交周旋與軍事行動。\\\\n\\\\n【詞義與名物】\\\\n「君臣」：指各國的統治者與輔佐之臣。\\\\n「戰國」：時代背景，羣雄並起。\\\\n\\\\n【縱橫機謋】\\\\n段落中展現了典型的戰國策士風範。他們善於揣摩人心，分析利害關係，並利用各國之間的矛盾與利益衝突，提出巧言善辯的策略，以達到保全自身或削弱敵國的政治目的。"}},{"id":"zhan-guo-ce_ch-1_p-27","chapterId":"zhan-guo-ce_ch-1","order":27,"canonicalText":"昌他亡西周，之東周，盡輸西周之情於東周。東周大喜，西周大怒。馮且曰：「臣能殺之。」君予金三十斤。馮且使人操金與書，間遺昌他書曰：「告昌他，事可成，勉成之；不可成，亟亡來亡來。事久且泄，自令身死。」因使人告東周之侯曰：「今夕有姦人當入者矣。」候得而獻東周，東周立殺昌他。","sentenceIds":["zhan-guo-ce_ch-1_p-27_s-1","zhan-guo-ce_ch-1_p-27_s-2","zhan-guo-ce_ch-1_p-27_s-3","zhan-guo-ce_ch-1_p-27_s-4","zhan-guo-ce_ch-1_p-27_s-5","zhan-guo-ce_ch-1_p-27_s-6","zhan-guo-ce_ch-1_p-27_s-7","zhan-guo-ce_ch-1_p-27_s-8","zhan-guo-ce_ch-1_p-27_s-9"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/zhan-guo-ce/zh"}],"readingAid":{"translation":"這是一段來自戰國策的歷史敘述，記載了當時各國君臣之間的政治對話與外交策略。具體描述了相關人物在面對國家危機或戰略抉擇時的應對之策（段落編號：23）。","analysis":"【主題與背景】\\\\n本段落（23）反映了戰國時期諸侯國之間錯綜複雜的政治角力與軍事衝突。當時各國為了爭奪霸權或尋求生存，頻繁展開外交周旋與軍事行動。\\\\n\\\\n【詞義與名物】\\\\n「君臣」：指各國的統治者與輔佐之臣。\\\\n「戰國」：時代背景，羣雄並起。\\\\n\\\\n【縱橫機謋】\\\\n段落中展現了典型的戰國策士風範。他們善於揣摩人心，分析利害關係，並利用各國之間的矛盾與利益衝突，提出巧言善辯的策略，以達到保全自身或削弱敵國的政治目的。"}},{"id":"zhan-guo-ce_ch-1_p-28","chapterId":"zhan-guo-ce_ch-1","order":28,"canonicalText":"昭翦與東周惡，或謂照翦曰：「為公畫陰計。」照翦曰：「何也？」「西周甚憎東周，嘗欲東周與楚惡，西周必令賊賊公，因宣言東周也，以西周之於王也。」照翦曰：「善。吾又恐東周之賊己而以輕西周惡之於楚。」遽和東周。","sentenceIds":["zhan-guo-ce_ch-1_p-28_s-1","zhan-guo-ce_ch-1_p-28_s-2","zhan-guo-ce_ch-1_p-28_s-3","zhan-guo-ce_ch-1_p-28_s-4","zhan-guo-ce_ch-1_p-28_s-5","zhan-guo-ce_ch-1_p-28_s-6"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/zhan-guo-ce/zh"}],"readingAid":{"translation":"這是一段來自戰國策的歷史敘述，記載了當時各國君臣之間的政治對話與外交策略。具體描述了相關人物在面對國家危機或戰略抉擇時的應對之策（段落編號：24）。","analysis":"【主題與背景】\\\\n本段落（24）反映了戰國時期諸侯國之間錯綜複雜的政治角力與軍事衝突。當時各國為了爭奪霸權或尋求生存，頻繁展開外交周旋與軍事行動。\\\\n\\\\n【詞義與名物】\\\\n「君臣」：指各國的統治者與輔佐之臣。\\\\n「戰國」：時代背景，羣雄並起。\\\\n\\\\n【縱橫機謋】\\\\n段落中展現了典型的戰國策士風範。他們善於揣摩人心，分析利害關係，並利用各國之間的矛盾與利益衝突，提出巧言善辯的策略，以達到保全自身或削弱敵國的政治目的。"}},{"id":"zhan-guo-ce_ch-1_p-29","chapterId":"zhan-guo-ce_ch-1","order":29,"canonicalText":"嚴氏為賊，而陽堅與焉。道周，周君留之十四日，載以乘車駟馬而遣之。韓使人讓周，周君患之。客謂周君曰：「正語之曰：『寡人知嚴氏之為賊，而陽堅與之，故留之十四日以待命也。小國不足亦以容賊，君之使又不至，是以遣之也。』」","sentenceIds":["zhan-guo-ce_ch-1_p-29_s-1","zhan-guo-ce_ch-1_p-29_s-2","zhan-guo-ce_ch-1_p-29_s-3","zhan-guo-ce_ch-1_p-29_s-4","zhan-guo-ce_ch-1_p-29_s-5","zhan-guo-ce_ch-1_p-29_s-6"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/zhan-guo-ce/zh"}],"readingAid":{"translation":"本段典籍核心大意在於闡述現代維度的價值理念。具體而言，文言語意涵蓋了有關正面光明、規律與原理、統治者、眾人、統治者、統治者、講述、講述、眾人、正面光明、社稷諸侯、統治者的深層觀點，揭示了事物運作與組織管理之法則。全段旨在提醒人們在處世與決策時應保持清醒的洞察力。〔《戰國策》〈東周〉第29節導讀〕","analysis":"【主旨】本段聚焦於《戰國策》的核心議題，解析了當前章節的精髓與核心觀念。\\n【關鍵詞義】「嚴」──古漢語核心意象與經典表達；「氏」──古漢語核心意象與經典表達；「為」──古漢語核心意象與經典表達；「賊」──古漢語核心意象與經典表達\\n【思想脈絡】段落結構嚴謹，語意層次分明。從「嚴」出發，漸次遞進至全篇哲理宏旨。\\n【當代啟示】提示現代人在面對複雜情境時，應汲取古代智慧，保持理性與定力。"}}],"sentences":[{"id":"zhan-guo-ce_ch-1_p-1_s-1","passageId":"zhan-guo-ce_ch-1_p-1","order":1,"canonicalText":"秦興師臨周而求九鼎，周君患之，以告顏率。","chunks":[["秦興師臨周而求九鼎，周君患之，以告顏率。","zh-Hant"]]},{"id":"zhan-guo-ce_ch-1_p-1_s-2","passageId":"zhan-guo-ce_ch-1_p-1","order":2,"canonicalText":"顏率曰：「大王勿憂，臣請東借救於齊。","chunks":[["顏率曰：「大王勿憂，臣請東借救於齊。","zh-Hant"]]},{"id":"zhan-guo-ce_ch-1_p-1_s-3","passageId":"zhan-guo-ce_ch-1_p-1","order":3,"canonicalText":"」顏率至齊，謂齊王曰：「夫秦之為無道也，欲興兵臨周而求九鼎，周之君臣，內自盡計，與秦，不若歸之大國。","chunks":[["」顏率至齊，謂齊王曰：「夫秦之為無道也，欲興兵臨周而求九鼎，周之君臣，內自盡計，與秦，不若歸之大國。","zh-Hant"]]},{"id":"zhan-guo-ce_ch-1_p-1_s-4","passageId":"zhan-guo-ce_ch-1_p-1","order":4,"canonicalText":"夫存危國，美名也；","chunks":[["夫存危國，美名也；","zh-Hant"]]},{"id":"zhan-guo-ce_ch-1_p-1_s-5","passageId":"zhan-guo-ce_ch-1_p-1","order":5,"canonicalText":"得九鼎，厚寶也。","chunks":[["得九鼎，厚寶也。","zh-Hant"]]},{"id":"zhan-guo-ce_ch-1_p-1_s-6","passageId":"zhan-guo-ce_ch-1_p-1","order":6,"canonicalText":"願大王圖之。","chunks":[["願大王圖之。","zh-Hant"]]},{"id":"zhan-guo-ce_ch-1_p-1_s-7","passageId":"zhan-guo-ce_ch-1_p-1","order":7,"canonicalText":"」齊王大悅，發師五萬人，使陳臣思將以救周，而秦兵罷。","chunks":[["」齊王大悅，發師五萬人，使陳臣思將以救周，而秦兵罷。","zh-Hant"]]},{"id":"zhan-guo-ce_ch-1_p-2_s-1","passageId":"zhan-guo-ce_ch-1_p-2","order":1,"canonicalText":"齊將求九鼎，周君又患之。","chunks":[["齊將求九鼎，周君又患之。","zh-Hant"]]},{"id":"zhan-guo-ce_ch-1_p-2_s-2","passageId":"zhan-guo-ce_ch-1_p-2","order":2,"canonicalText":"顏率曰：「大王勿憂，臣請東解之。","chunks":[["顏率曰：「大王勿憂，臣請東解之。","zh-Hant"]]},{"id":"zhan-guo-ce_ch-1_p-2_s-3","passageId":"zhan-guo-ce_ch-1_p-2","order":3,"canonicalText":"」顏率至齊，謂齊王曰：「周賴大國之義，得君臣父子相保也，願獻九鼎，不識大國何塗之從而致齊？","chunks":[["」顏率至齊，謂齊王曰：「周賴大國之義，得君臣父子相保也，願獻九鼎，不識大國何塗之從而致齊？","zh-Hant"]]},{"id":"zhan-guo-ce_ch-1_p-2_s-4","passageId":"zhan-guo-ce_ch-1_p-2","order":4,"canonicalText":"」齊王曰：「寡人將寄徑於梁。","chunks":[["」齊王曰：「寡人將寄徑於梁。","zh-Hant"]]},{"id":"zhan-guo-ce_ch-1_p-2_s-5","passageId":"zhan-guo-ce_ch-1_p-2","order":5,"canonicalText":"」顏率曰：「不可。","chunks":[["」顏率曰：「不可。","zh-Hant"]]},{"id":"zhan-guo-ce_ch-1_p-2_s-6","passageId":"zhan-guo-ce_ch-1_p-2","order":6,"canonicalText":"夫梁之君臣欲得九鼎，謀之暉臺之下，少海之上，其日久矣。","chunks":[["夫梁之君臣欲得九鼎，謀之暉臺之下，少海之上，其日久矣。","zh-Hant"]]},{"id":"zhan-guo-ce_ch-1_p-2_s-7","passageId":"zhan-guo-ce_ch-1_p-2","order":7,"canonicalText":"鼎入梁，必不出。","chunks":[["鼎入梁，必不出。","zh-Hant"]]},{"id":"zhan-guo-ce_ch-1_p-2_s-8","passageId":"zhan-guo-ce_ch-1_p-2","order":8,"canonicalText":"」齊王曰：「寡人將寄徑於楚。","chunks":[["」齊王曰：「寡人將寄徑於楚。","zh-Hant"]]},{"id":"zhan-guo-ce_ch-1_p-2_s-9","passageId":"zhan-guo-ce_ch-1_p-2","order":9,"canonicalText":"」對曰：「不可。","chunks":[["」對曰：「不可。","zh-Hant"]]},{"id":"zhan-guo-ce_ch-1_p-2_s-10","passageId":"zhan-guo-ce_ch-1_p-2","order":10,"canonicalText":"楚之君臣欲得九鼎，謀之於葉庭之中，其日久矣。","chunks":[["楚之君臣欲得九鼎，謀之於葉庭之中，其日久矣。","zh-Hant"]]},{"id":"zhan-guo-ce_ch-1_p-2_s-11","passageId":"zhan-guo-ce_ch-1_p-2","order":11,"canonicalText":"若入楚，鼎必不出。","chunks":[["若入楚，鼎必不出。","zh-Hant"]]},{"id":"zhan-guo-ce_ch-1_p-2_s-12","passageId":"zhan-guo-ce_ch-1_p-2","order":12,"canonicalText":"」王曰：「寡人終何塗之從而致之齊？","chunks":[["」王曰：「寡人終何塗之從而致之齊？","zh-Hant"]]},{"id":"zhan-guo-ce_ch-1_p-2_s-13","passageId":"zhan-guo-ce_ch-1_p-2","order":13,"canonicalText":"」顏率曰：「弊邑固竊為大王患之。","chunks":[["」顏率曰：「弊邑固竊為大王患之。","zh-Hant"]]},{"id":"zhan-guo-ce_ch-1_p-2_s-14","passageId":"zhan-guo-ce_ch-1_p-2","order":14,"canonicalText":"夫鼎者，非效醯壺醬垂耳，可懷挾提挈以至齊者；","chunks":[["夫鼎者，非效醯壺醬垂耳，可懷挾提挈以至齊者；","zh-Hant"]]},{"id":"zhan-guo-ce_ch-1_p-2_s-15","passageId":"zhan-guo-ce_ch-1_p-2","order":15,"canonicalText":"非效鳥集、烏飛、兔興、馬逝，灕然止於齊者。","chunks":[["非效鳥集、烏飛、兔興、馬逝，灕然止於齊者。","zh-Hant"]]},{"id":"zhan-guo-ce_ch-1_p-2_s-16","passageId":"zhan-guo-ce_ch-1_p-2","order":16,"canonicalText":"昔周之伐殷，得九鼎，凡一鼎而九萬人輓之，九九八十一萬人，士卒師徒，器械被具，所以備者稱此。","chunks":[["昔周之伐殷，得九鼎，凡一鼎而九萬人輓之，九九八十一萬人，士卒師徒，器械被具，所以備者稱此。","zh-Hant"]]},{"id":"zhan-guo-ce_ch-1_p-2_s-17","passageId":"zhan-guo-ce_ch-1_p-2","order":17,"canonicalText":"今大王縱有其人，何塗之從而出？","chunks":[["今大王縱有其人，何塗之從而出？","zh-Hant"]]},{"id":"zhan-guo-ce_ch-1_p-2_s-18","passageId":"zhan-guo-ce_ch-1_p-2","order":18,"canonicalText":"臣竊為大王私憂之。","chunks":[["臣竊為大王私憂之。","zh-Hant"]]},{"id":"zhan-guo-ce_ch-1_p-2_s-19","passageId":"zhan-guo-ce_ch-1_p-2","order":19,"canonicalText":"」齊王曰：「子之數來者，猶無與耳。","chunks":[["」齊王曰：「子之數來者，猶無與耳。","zh-Hant"]]},{"id":"zhan-guo-ce_ch-1_p-2_s-20","passageId":"zhan-guo-ce_ch-1_p-2","order":20,"canonicalText":"」顏率曰：「不敢欺大國，疾定所從出，弊邑遷鼎以待命。","chunks":[["」顏率曰：「不敢欺大國，疾定所從出，弊邑遷鼎以待命。","zh-Hant"]]},{"id":"zhan-guo-ce_ch-1_p-2_s-21","passageId":"zhan-guo-ce_ch-1_p-2","order":21,"canonicalText":"」齊王乃止。","chunks":[["」齊王乃止。","zh-Hant"]]},{"id":"zhan-guo-ce_ch-1_p-3_s-1","passageId":"zhan-guo-ce_ch-1_p-3","order":1,"canonicalText":"秦攻宜陽，周君謂趙累曰：「子以為何如？","chunks":[["秦攻宜陽，周君謂趙累曰：「子以為何如？","zh-Hant"]]},{"id":"zhan-guo-ce_ch-1_p-3_s-2","passageId":"zhan-guo-ce_ch-1_p-3","order":2,"canonicalText":"」對曰：「宜陽必拔也。","chunks":[["」對曰：「宜陽必拔也。","zh-Hant"]]},{"id":"zhan-guo-ce_ch-1_p-3_s-3","passageId":"zhan-guo-ce_ch-1_p-3","order":3,"canonicalText":"」君曰：「宜陽城方八里，材士十萬，粟支數年，公仲之軍二十萬，景翠以楚之眾，臨山而救之，秦必無功。","chunks":[["」君曰：「宜陽城方八里，材士十萬，粟支數年，公仲之軍二十萬，景翠以楚之眾，臨山而救之，秦必無功。","zh-Hant"]]},{"id":"zhan-guo-ce_ch-1_p-3_s-4","passageId":"zhan-guo-ce_ch-1_p-3","order":4,"canonicalText":"」對曰：「甘茂，羈旅也，攻宜陽而有功，則周公旦也；","chunks":[["」對曰：「甘茂，羈旅也，攻宜陽而有功，則周公旦也；","zh-Hant"]]},{"id":"zhan-guo-ce_ch-1_p-3_s-5","passageId":"zhan-guo-ce_ch-1_p-3","order":5,"canonicalText":"無功，則削跡於秦。","chunks":[["無功，則削跡於秦。","zh-Hant"]]},{"id":"zhan-guo-ce_ch-1_p-3_s-6","passageId":"zhan-guo-ce_ch-1_p-3","order":6,"canonicalText":"秦王不聽群臣父兄之義而攻宜陽，宜陽不拔，秦王恥之。","chunks":[["秦王不聽群臣父兄之義而攻宜陽，宜陽不拔，秦王恥之。","zh-Hant"]]},{"id":"zhan-guo-ce_ch-1_p-3_s-7","passageId":"zhan-guo-ce_ch-1_p-3","order":7,"canonicalText":"臣故曰拔。","chunks":[["臣故曰拔。","zh-Hant"]]},{"id":"zhan-guo-ce_ch-1_p-3_s-8","passageId":"zhan-guo-ce_ch-1_p-3","order":8,"canonicalText":"」君曰：「子為寡人謀，且奈何？","chunks":[["」君曰：「子為寡人謀，且奈何？","zh-Hant"]]},{"id":"zhan-guo-ce_ch-1_p-3_s-9","passageId":"zhan-guo-ce_ch-1_p-3","order":9,"canonicalText":"」對曰：「君謂景翠曰：『公爵為執圭，官為柱國，戰而勝，則無加焉矣；","chunks":[["」對曰：「君謂景翠曰：『公爵為執圭，官為柱國，戰而勝，則無加焉矣；","zh-Hant"]]},{"id":"zhan-guo-ce_ch-1_p-3_s-10","passageId":"zhan-guo-ce_ch-1_p-3","order":10,"canonicalText":"不勝，則死，不如背秦援宜陽，公進兵。","chunks":[["不勝，則死，不如背秦援宜陽，公進兵。","zh-Hant"]]},{"id":"zhan-guo-ce_ch-1_p-3_s-11","passageId":"zhan-guo-ce_ch-1_p-3","order":11,"canonicalText":"秦恐公之乘其弊也，必以寶事公；","chunks":[["秦恐公之乘其弊也，必以寶事公；","zh-Hant"]]},{"id":"zhan-guo-ce_ch-1_p-3_s-12","passageId":"zhan-guo-ce_ch-1_p-3","order":12,"canonicalText":"公中慕公之為己乘秦也，亦必盡其寶。","chunks":[["公中慕公之為己乘秦也，亦必盡其寶。","zh-Hant"]]},{"id":"zhan-guo-ce_ch-1_p-3_s-13","passageId":"zhan-guo-ce_ch-1_p-3","order":13,"canonicalText":"』」秦拔宜陽，景翠果進兵。","chunks":[["』」秦拔宜陽，景翠果進兵。","zh-Hant"]]},{"id":"zhan-guo-ce_ch-1_p-3_s-14","passageId":"zhan-guo-ce_ch-1_p-3","order":14,"canonicalText":"秦懼，遽效煮棗；","chunks":[["秦懼，遽效煮棗；","zh-Hant"]]},{"id":"zhan-guo-ce_ch-1_p-3_s-15","passageId":"zhan-guo-ce_ch-1_p-3","order":15,"canonicalText":"韓氏果亦效重寶。","chunks":[["韓氏果亦效重寶。","zh-Hant"]]},{"id":"zhan-guo-ce_ch-1_p-3_s-16","passageId":"zhan-guo-ce_ch-1_p-3","order":16,"canonicalText":"景翠得城於秦，受寶於韓，而德東周。","chunks":[["景翠得城於秦，受寶於韓，而德東周。","zh-Hant"]]},{"id":"zhan-guo-ce_ch-1_p-4_s-1","passageId":"zhan-guo-ce_ch-1_p-4","order":1,"canonicalText":"東周與西周戰，韓救西周。","chunks":[["東周與西周戰，韓救西周。","zh-Hant"]]},{"id":"zhan-guo-ce_ch-1_p-4_s-2","passageId":"zhan-guo-ce_ch-1_p-4","order":2,"canonicalText":"為東周謂韓王曰：「西周者，故天子之國也，多名器重寶。","chunks":[["為東周謂韓王曰：「西周者，故天子之國也，多名器重寶。","zh-Hant"]]},{"id":"zhan-guo-ce_ch-1_p-4_s-3","passageId":"zhan-guo-ce_ch-1_p-4","order":3,"canonicalText":"案兵而勿出，可以德東周，西周之寶可盡矣。","chunks":[["案兵而勿出，可以德東周，西周之寶可盡矣。","zh-Hant"]]},{"id":"zhan-guo-ce_ch-1_p-4_s-4","passageId":"zhan-guo-ce_ch-1_p-4","order":4,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"zhan-guo-ce_ch-1_p-5_s-1","passageId":"zhan-guo-ce_ch-1_p-5","order":1,"canonicalText":"東周與西周爭，西周欲和於楚、韓。","chunks":[["東周與西周爭，西周欲和於楚、韓。","zh-Hant"]]},{"id":"zhan-guo-ce_ch-1_p-5_s-2","passageId":"zhan-guo-ce_ch-1_p-5","order":2,"canonicalText":"齊明謂東周君曰：「臣恐西周之與楚、韓寶，令之為己求地於東周也。","chunks":[["齊明謂東周君曰：「臣恐西周之與楚、韓寶，令之為己求地於東周也。","zh-Hant"]]},{"id":"zhan-guo-ce_ch-1_p-5_s-3","passageId":"zhan-guo-ce_ch-1_p-5","order":3,"canonicalText":"不如謂楚、韓曰：『西周之欲入寶，持二端。","chunks":[["不如謂楚、韓曰：『西周之欲入寶，持二端。","zh-Hant"]]},{"id":"zhan-guo-ce_ch-1_p-5_s-4","passageId":"zhan-guo-ce_ch-1_p-5","order":4,"canonicalText":"今東周之兵不急西周，西周之寶不入楚、韓。","chunks":[["今東周之兵不急西周，西周之寶不入楚、韓。","zh-Hant"]]},{"id":"zhan-guo-ce_ch-1_p-5_s-5","passageId":"zhan-guo-ce_ch-1_p-5","order":5,"canonicalText":"』楚、韓欲得寶，即且趣我攻西周。","chunks":[["』楚、韓欲得寶，即且趣我攻西周。","zh-Hant"]]},{"id":"zhan-guo-ce_ch-1_p-5_s-6","passageId":"zhan-guo-ce_ch-1_p-5","order":6,"canonicalText":"西周寶出，是我為楚、韓取寶以德之也，西周弱矣。","chunks":[["西周寶出，是我為楚、韓取寶以德之也，西周弱矣。","zh-Hant"]]},{"id":"zhan-guo-ce_ch-1_p-5_s-7","passageId":"zhan-guo-ce_ch-1_p-5","order":7,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"zhan-guo-ce_ch-1_p-6_s-1","passageId":"zhan-guo-ce_ch-1_p-6","order":1,"canonicalText":"東周欲為稻，西周不下水，東周患之。","chunks":[["東周欲為稻，西周不下水，東周患之。","zh-Hant"]]},{"id":"zhan-guo-ce_ch-1_p-6_s-2","passageId":"zhan-guo-ce_ch-1_p-6","order":2,"canonicalText":"蘇子謂東周君曰：「臣請使西周下水可乎？","chunks":[["蘇子謂東周君曰：「臣請使西周下水可乎？","zh-Hant"]]},{"id":"zhan-guo-ce_ch-1_p-6_s-3","passageId":"zhan-guo-ce_ch-1_p-6","order":3,"canonicalText":"」乃往見西周之君曰：「君之謀過矣！","chunks":[["」乃往見西周之君曰：「君之謀過矣！","zh-Hant"]]},{"id":"zhan-guo-ce_ch-1_p-6_s-4","passageId":"zhan-guo-ce_ch-1_p-6","order":4,"canonicalText":"今不下水，所以富東周也。","chunks":[["今不下水，所以富東周也。","zh-Hant"]]},{"id":"zhan-guo-ce_ch-1_p-6_s-5","passageId":"zhan-guo-ce_ch-1_p-6","order":5,"canonicalText":"今其民皆種麥，無他種矣。","chunks":[["今其民皆種麥，無他種矣。","zh-Hant"]]},{"id":"zhan-guo-ce_ch-1_p-6_s-6","passageId":"zhan-guo-ce_ch-1_p-6","order":6,"canonicalText":"君若欲害之，不若一為下水，以病其所種。","chunks":[["君若欲害之，不若一為下水，以病其所種。","zh-Hant"]]},{"id":"zhan-guo-ce_ch-1_p-6_s-7","passageId":"zhan-guo-ce_ch-1_p-6","order":7,"canonicalText":"下水，東周必復種稻；","chunks":[["下水，東周必復種稻；","zh-Hant"]]},{"id":"zhan-guo-ce_ch-1_p-6_s-8","passageId":"zhan-guo-ce_ch-1_p-6","order":8,"canonicalText":"種稻而復奪之。","chunks":[["種稻而復奪之。","zh-Hant"]]},{"id":"zhan-guo-ce_ch-1_p-6_s-9","passageId":"zhan-guo-ce_ch-1_p-6","order":9,"canonicalText":"若是，則東周之民可令一仰西周，而受命於君矣。","chunks":[["若是，則東周之民可令一仰西周，而受命於君矣。","zh-Hant"]]},{"id":"zhan-guo-ce_ch-1_p-6_s-10","passageId":"zhan-guo-ce_ch-1_p-6","order":10,"canonicalText":"」西周君曰：「善。","chunks":[["」西周君曰：「善。","zh-Hant"]]},{"id":"zhan-guo-ce_ch-1_p-6_s-11","passageId":"zhan-guo-ce_ch-1_p-6","order":11,"canonicalText":"」遂下水。","chunks":[["」遂下水。","zh-Hant"]]},{"id":"zhan-guo-ce_ch-1_p-6_s-12","passageId":"zhan-guo-ce_ch-1_p-6","order":12,"canonicalText":"蘇子亦得兩國之金也。","chunks":[["蘇子亦得兩國之金也。","zh-Hant"]]},{"id":"zhan-guo-ce_ch-1_p-7_s-1","passageId":"zhan-guo-ce_ch-1_p-7","order":1,"canonicalText":"昭獻在陽翟，周君將令相國往，相國將不欲。","chunks":[["昭獻在陽翟，周君將令相國往，相國將不欲。","zh-Hant"]]},{"id":"zhan-guo-ce_ch-1_p-7_s-2","passageId":"zhan-guo-ce_ch-1_p-7","order":2,"canonicalText":"蘇厲為之謂周君曰：「楚王與魏王遇也，主君令陳封之楚，令向公之魏；","chunks":[["蘇厲為之謂周君曰：「楚王與魏王遇也，主君令陳封之楚，令向公之魏；","zh-Hant"]]},{"id":"zhan-guo-ce_ch-1_p-7_s-3","passageId":"zhan-guo-ce_ch-1_p-7","order":3,"canonicalText":"楚、韓之遇也，主君令許公之楚，令向公之韓。","chunks":[["楚、韓之遇也，主君令許公之楚，令向公之韓。","zh-Hant"]]},{"id":"zhan-guo-ce_ch-1_p-7_s-4","passageId":"zhan-guo-ce_ch-1_p-7","order":4,"canonicalText":"今昭獻非人主也，而主君令相國往，若其王在陽翟，主君將令誰往？","chunks":[["今昭獻非人主也，而主君令相國往，若其王在陽翟，主君將令誰往？","zh-Hant"]]},{"id":"zhan-guo-ce_ch-1_p-7_s-5","passageId":"zhan-guo-ce_ch-1_p-7","order":5,"canonicalText":"」周君曰：「善。","chunks":[["」周君曰：「善。","zh-Hant"]]},{"id":"zhan-guo-ce_ch-1_p-7_s-6","passageId":"zhan-guo-ce_ch-1_p-7","order":6,"canonicalText":"」乃止其行。","chunks":[["」乃止其行。","zh-Hant"]]},{"id":"zhan-guo-ce_ch-1_p-8_s-1","passageId":"zhan-guo-ce_ch-1_p-8","order":1,"canonicalText":"秦假道於周以伐韓，周恐假之而惡於韓，不假而惡於秦。","chunks":[["秦假道於周以伐韓，周恐假之而惡於韓，不假而惡於秦。","zh-Hant"]]},{"id":"zhan-guo-ce_ch-1_p-8_s-2","passageId":"zhan-guo-ce_ch-1_p-8","order":2,"canonicalText":"史黶謂周君曰：「君何不令人謂韓公叔曰：『秦敢絕塞而伐韓者，信東周也。","chunks":[["史黶謂周君曰：「君何不令人謂韓公叔曰：『秦敢絕塞而伐韓者，信東周也。","zh-Hant"]]},{"id":"zhan-guo-ce_ch-1_p-8_s-3","passageId":"zhan-guo-ce_ch-1_p-8","order":3,"canonicalText":"公何不與周地，發重使使之楚，秦必疑，不信周，是韓不伐也。","chunks":[["公何不與周地，發重使使之楚，秦必疑，不信周，是韓不伐也。","zh-Hant"]]},{"id":"zhan-guo-ce_ch-1_p-8_s-4","passageId":"zhan-guo-ce_ch-1_p-8","order":4,"canonicalText":"』又謂秦王曰：『韓強與周地，將以疑周於秦，寡人不敢弗受。","chunks":[["』又謂秦王曰：『韓強與周地，將以疑周於秦，寡人不敢弗受。","zh-Hant"]]},{"id":"zhan-guo-ce_ch-1_p-8_s-5","passageId":"zhan-guo-ce_ch-1_p-8","order":5,"canonicalText":"』秦必無辭而令周弗受，是得地於韓而聽於秦也。","chunks":[["』秦必無辭而令周弗受，是得地於韓而聽於秦也。","zh-Hant"]]},{"id":"zhan-guo-ce_ch-1_p-8_s-6","passageId":"zhan-guo-ce_ch-1_p-8","order":6,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"zhan-guo-ce_ch-1_p-9_s-1","passageId":"zhan-guo-ce_ch-1_p-9","order":1,"canonicalText":"楚攻雍氏，周餦秦、韓，楚王怒周，周之君患之。","chunks":[["楚攻雍氏，周餦秦、韓，楚王怒周，周之君患之。","zh-Hant"]]},{"id":"zhan-guo-ce_ch-1_p-9_s-2","passageId":"zhan-guo-ce_ch-1_p-9","order":2,"canonicalText":"為周謂楚王曰：「以王之強而怒周，周恐，必以國合於所與粟之國，則是勁王之敵也。","chunks":[["為周謂楚王曰：「以王之強而怒周，周恐，必以國合於所與粟之國，則是勁王之敵也。","zh-Hant"]]},{"id":"zhan-guo-ce_ch-1_p-9_s-3","passageId":"zhan-guo-ce_ch-1_p-9","order":3,"canonicalText":"故王不如速解周恐，彼前得罪而後得解，必厚事王矣。","chunks":[["故王不如速解周恐，彼前得罪而後得解，必厚事王矣。","zh-Hant"]]},{"id":"zhan-guo-ce_ch-1_p-9_s-4","passageId":"zhan-guo-ce_ch-1_p-9","order":4,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"zhan-guo-ce_ch-1_p-10_s-1","passageId":"zhan-guo-ce_ch-1_p-10","order":1,"canonicalText":"周最謂石禮曰：「子何不以秦攻齊？","chunks":[["周最謂石禮曰：「子何不以秦攻齊？","zh-Hant"]]},{"id":"zhan-guo-ce_ch-1_p-10_s-2","passageId":"zhan-guo-ce_ch-1_p-10","order":2,"canonicalText":"臣請令齊相子，子以齊事秦，必無處矣。","chunks":[["臣請令齊相子，子以齊事秦，必無處矣。","zh-Hant"]]},{"id":"zhan-guo-ce_ch-1_p-10_s-3","passageId":"zhan-guo-ce_ch-1_p-10","order":3,"canonicalText":"子因令周最居魏以共之，是天下制於子也。","chunks":[["子因令周最居魏以共之，是天下制於子也。","zh-Hant"]]},{"id":"zhan-guo-ce_ch-1_p-10_s-4","passageId":"zhan-guo-ce_ch-1_p-10","order":4,"canonicalText":"子東重於齊，西貴於秦，秦、齊合，則子常重矣。","chunks":[["子東重於齊，西貴於秦，秦、齊合，則子常重矣。","zh-Hant"]]},{"id":"zhan-guo-ce_ch-1_p-10_s-5","passageId":"zhan-guo-ce_ch-1_p-10","order":5,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"zhan-guo-ce_ch-1_p-11_s-1","passageId":"zhan-guo-ce_ch-1_p-11","order":1,"canonicalText":"周相呂倉見客於周君。","chunks":[["周相呂倉見客於周君。","zh-Hant"]]},{"id":"zhan-guo-ce_ch-1_p-11_s-2","passageId":"zhan-guo-ce_ch-1_p-11","order":2,"canonicalText":"前相工師籍恐客之傷己也，因令人謂周君曰：「客者，辯士也，然而所以不可者，好毀人。","chunks":[["前相工師籍恐客之傷己也，因令人謂周君曰：「客者，辯士也，然而所以不可者，好毀人。","zh-Hant"]]},{"id":"zhan-guo-ce_ch-1_p-11_s-3","passageId":"zhan-guo-ce_ch-1_p-11","order":3,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"zhan-guo-ce_ch-1_p-12_s-1","passageId":"zhan-guo-ce_ch-1_p-12","order":1,"canonicalText":"周文君免士工師籍，相呂倉，國人不說也。","chunks":[["周文君免士工師籍，相呂倉，國人不說也。","zh-Hant"]]},{"id":"zhan-guo-ce_ch-1_p-12_s-2","passageId":"zhan-guo-ce_ch-1_p-12","order":2,"canonicalText":"君有閔閔之心。","chunks":[["君有閔閔之心。","zh-Hant"]]},{"id":"zhan-guo-ce_ch-1_p-12_s-3","passageId":"zhan-guo-ce_ch-1_p-12","order":3,"canonicalText":"謂周文君曰：「國必有誹譽，忠臣令誹在己，譽在上。","chunks":[["謂周文君曰：「國必有誹譽，忠臣令誹在己，譽在上。","zh-Hant"]]},{"id":"zhan-guo-ce_ch-1_p-12_s-4","passageId":"zhan-guo-ce_ch-1_p-12","order":4,"canonicalText":"宋君奪民時以為臺，而非民之，無忠臣以掩蓋之也，子罕釋相為司空，民非子罕而善其君；","chunks":[["宋君奪民時以為臺，而非民之，無忠臣以掩蓋之也，子罕釋相為司空，民非子罕而善其君；","zh-Hant"]]},{"id":"zhan-guo-ce_ch-1_p-12_s-5","passageId":"zhan-guo-ce_ch-1_p-12","order":5,"canonicalText":"齊桓公宮中七市，女閭七百，國人非之，管仲故為三歸之家，以掩桓公，非自傷於民也。","chunks":[["齊桓公宮中七市，女閭七百，國人非之，管仲故為三歸之家，以掩桓公，非自傷於民也。","zh-Hant"]]},{"id":"zhan-guo-ce_ch-1_p-12_s-6","passageId":"zhan-guo-ce_ch-1_p-12","order":6,"canonicalText":"《春秋》記臣弒君者以百數，皆大臣見譽者也。","chunks":[["《春秋》記臣弒君者以百數，皆大臣見譽者也。","zh-Hant"]]},{"id":"zhan-guo-ce_ch-1_p-12_s-7","passageId":"zhan-guo-ce_ch-1_p-12","order":7,"canonicalText":"故大臣得譽，非國家之美也。","chunks":[["故大臣得譽，非國家之美也。","zh-Hant"]]},{"id":"zhan-guo-ce_ch-1_p-12_s-8","passageId":"zhan-guo-ce_ch-1_p-12","order":8,"canonicalText":"故眾庶成彊，增積成山。","chunks":[["故眾庶成彊，增積成山。","zh-Hant"]]},{"id":"zhan-guo-ce_ch-1_p-12_s-9","passageId":"zhan-guo-ce_ch-1_p-12","order":9,"canonicalText":"」周君遂不免。","chunks":[["」周君遂不免。","zh-Hant"]]},{"id":"zhan-guo-ce_ch-1_p-13_s-1","passageId":"zhan-guo-ce_ch-1_p-13","order":1,"canonicalText":"溫人之周，周不納。","chunks":[["溫人之周，周不納。","zh-Hant"]]},{"id":"zhan-guo-ce_ch-1_p-13_s-2","passageId":"zhan-guo-ce_ch-1_p-13","order":2,"canonicalText":"「客即？","chunks":[["「客即？","zh-Hant"]]},{"id":"zhan-guo-ce_ch-1_p-13_s-3","passageId":"zhan-guo-ce_ch-1_p-13","order":3,"canonicalText":"」對曰：「主人也。","chunks":[["」對曰：「主人也。","zh-Hant"]]},{"id":"zhan-guo-ce_ch-1_p-13_s-4","passageId":"zhan-guo-ce_ch-1_p-13","order":4,"canonicalText":"」問其巷而不知也，使因囚之。","chunks":[["」問其巷而不知也，使因囚之。","zh-Hant"]]},{"id":"zhan-guo-ce_ch-1_p-13_s-5","passageId":"zhan-guo-ce_ch-1_p-13","order":5,"canonicalText":"君使人問之曰：「子非周人，而自謂非客何也？","chunks":[["君使人問之曰：「子非周人，而自謂非客何也？","zh-Hant"]]},{"id":"zhan-guo-ce_ch-1_p-13_s-6","passageId":"zhan-guo-ce_ch-1_p-13","order":6,"canonicalText":"」對曰：「臣少而誦《》，《》曰：『普天之下，莫非王土；","chunks":[["」對曰：「臣少而誦《》，《》曰：『普天之下，莫非王土；","zh-Hant"]]},{"id":"zhan-guo-ce_ch-1_p-13_s-7","passageId":"zhan-guo-ce_ch-1_p-13","order":7,"canonicalText":"率土之濱，莫非王臣。","chunks":[["率土之濱，莫非王臣。","zh-Hant"]]},{"id":"zhan-guo-ce_ch-1_p-13_s-8","passageId":"zhan-guo-ce_ch-1_p-13","order":8,"canonicalText":"』今周君天下，則我天子之臣，而又為客哉？","chunks":[["』今周君天下，則我天子之臣，而又為客哉？","zh-Hant"]]},{"id":"zhan-guo-ce_ch-1_p-13_s-9","passageId":"zhan-guo-ce_ch-1_p-13","order":9,"canonicalText":"故曰主人。","chunks":[["故曰主人。","zh-Hant"]]},{"id":"zhan-guo-ce_ch-1_p-13_s-10","passageId":"zhan-guo-ce_ch-1_p-13","order":10,"canonicalText":"」君乃使吏出之。","chunks":[["」君乃使吏出之。","zh-Hant"]]},{"id":"zhan-guo-ce_ch-1_p-14_s-1","passageId":"zhan-guo-ce_ch-1_p-14","order":1,"canonicalText":"或為周最謂金投曰：「秦以周最之齊疑天下，而又知趙之難子齊人戰，恐齊、韓之合，必先合於秦。","chunks":[["或為周最謂金投曰：「秦以周最之齊疑天下，而又知趙之難子齊人戰，恐齊、韓之合，必先合於秦。","zh-Hant"]]},{"id":"zhan-guo-ce_ch-1_p-14_s-2","passageId":"zhan-guo-ce_ch-1_p-14","order":2,"canonicalText":"秦、齊合，則公之國虛矣。","chunks":[["秦、齊合，則公之國虛矣。","zh-Hant"]]},{"id":"zhan-guo-ce_ch-1_p-14_s-3","passageId":"zhan-guo-ce_ch-1_p-14","order":3,"canonicalText":"公不如救齊，因佐秦而伐韓、魏，上黨、長子趙之有。","chunks":[["公不如救齊，因佐秦而伐韓、魏，上黨、長子趙之有。","zh-Hant"]]},{"id":"zhan-guo-ce_ch-1_p-14_s-4","passageId":"zhan-guo-ce_ch-1_p-14","order":4,"canonicalText":"公東收寶於秦，南取地於韓，魏因以因，徐為之東，則有合矣。","chunks":[["公東收寶於秦，南取地於韓，魏因以因，徐為之東，則有合矣。","zh-Hant"]]},{"id":"zhan-guo-ce_ch-1_p-14_s-5","passageId":"zhan-guo-ce_ch-1_p-14","order":5,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"zhan-guo-ce_ch-1_p-15_s-1","passageId":"zhan-guo-ce_ch-1_p-15","order":1,"canonicalText":"周最謂金投曰：「公負令秦與強齊戰。","chunks":[["周最謂金投曰：「公負令秦與強齊戰。","zh-Hant"]]},{"id":"zhan-guo-ce_ch-1_p-15_s-2","passageId":"zhan-guo-ce_ch-1_p-15","order":2,"canonicalText":"戰勝，秦且收齊而封之，使無多割，而聽天下之戰；","chunks":[["戰勝，秦且收齊而封之，使無多割，而聽天下之戰；","zh-Hant"]]},{"id":"zhan-guo-ce_ch-1_p-15_s-3","passageId":"zhan-guo-ce_ch-1_p-15","order":3,"canonicalText":"不勝，國大傷，不得不聽秦。","chunks":[["不勝，國大傷，不得不聽秦。","zh-Hant"]]},{"id":"zhan-guo-ce_ch-1_p-15_s-4","passageId":"zhan-guo-ce_ch-1_p-15","order":4,"canonicalText":"秦盡韓、魏之上黨、太原，西止秦之有已。","chunks":[["秦盡韓、魏之上黨、太原，西止秦之有已。","zh-Hant"]]},{"id":"zhan-guo-ce_ch-1_p-15_s-5","passageId":"zhan-guo-ce_ch-1_p-15","order":5,"canonicalText":"秦地，天下之半也，制齊、楚、三晉之命，復國且身危，是何計之道也。","chunks":[["秦地，天下之半也，制齊、楚、三晉之命，復國且身危，是何計之道也。","zh-Hant"]]},{"id":"zhan-guo-ce_ch-1_p-15_s-6","passageId":"zhan-guo-ce_ch-1_p-15","order":6,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"zhan-guo-ce_ch-1_p-16_s-1","passageId":"zhan-guo-ce_ch-1_p-16","order":1,"canonicalText":"石行秦謂大梁造曰：「欲決霸王之名，不如備兩周辯知之士。","chunks":[["石行秦謂大梁造曰：「欲決霸王之名，不如備兩周辯知之士。","zh-Hant"]]},{"id":"zhan-guo-ce_ch-1_p-16_s-2","passageId":"zhan-guo-ce_ch-1_p-16","order":2,"canonicalText":"」謂周君曰：「君不如令辯知之士，為君爭於秦。","chunks":[["」謂周君曰：「君不如令辯知之士，為君爭於秦。","zh-Hant"]]},{"id":"zhan-guo-ce_ch-1_p-16_s-3","passageId":"zhan-guo-ce_ch-1_p-16","order":3,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"zhan-guo-ce_ch-1_p-17_s-1","passageId":"zhan-guo-ce_ch-1_p-17","order":1,"canonicalText":"謂薛公曰：「周最於齊王也而逐之，聽祝弗，相呂禮者，欲取秦。","chunks":[["謂薛公曰：「周最於齊王也而逐之，聽祝弗，相呂禮者，欲取秦。","zh-Hant"]]},{"id":"zhan-guo-ce_ch-1_p-17_s-2","passageId":"zhan-guo-ce_ch-1_p-17","order":2,"canonicalText":"秦、齊合，弗與禮重矣。","chunks":[["秦、齊合，弗與禮重矣。","zh-Hant"]]},{"id":"zhan-guo-ce_ch-1_p-17_s-3","passageId":"zhan-guo-ce_ch-1_p-17","order":3,"canonicalText":"有周齊，秦必輕君。","chunks":[["有周齊，秦必輕君。","zh-Hant"]]},{"id":"zhan-guo-ce_ch-1_p-17_s-4","passageId":"zhan-guo-ce_ch-1_p-17","order":4,"canonicalText":"君弗如急北兵，趨趙以秦、魏，收周最以為後行，且反齊王之信，又禁天下之率。","chunks":[["君弗如急北兵，趨趙以秦、魏，收周最以為後行，且反齊王之信，又禁天下之率。","zh-Hant"]]},{"id":"zhan-guo-ce_ch-1_p-17_s-5","passageId":"zhan-guo-ce_ch-1_p-17","order":5,"canonicalText":"齊無秦，天下果，弗必走，齊王誰與為其國？","chunks":[["齊無秦，天下果，弗必走，齊王誰與為其國？","zh-Hant"]]},{"id":"zhan-guo-ce_ch-1_p-17_s-6","passageId":"zhan-guo-ce_ch-1_p-17","order":6,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"zhan-guo-ce_ch-1_p-18_s-1","passageId":"zhan-guo-ce_ch-1_p-18","order":1,"canonicalText":"齊聽祝弗，外周最。","chunks":[["齊聽祝弗，外周最。","zh-Hant"]]},{"id":"zhan-guo-ce_ch-1_p-18_s-2","passageId":"zhan-guo-ce_ch-1_p-18","order":2,"canonicalText":"謂齊王曰：「逐周最、聽祝弗、相呂禮者，欲深取秦也。","chunks":[["謂齊王曰：「逐周最、聽祝弗、相呂禮者，欲深取秦也。","zh-Hant"]]},{"id":"zhan-guo-ce_ch-1_p-18_s-3","passageId":"zhan-guo-ce_ch-1_p-18","order":3,"canonicalText":"秦得天下，則伐齊深矣。","chunks":[["秦得天下，則伐齊深矣。","zh-Hant"]]},{"id":"zhan-guo-ce_ch-1_p-18_s-4","passageId":"zhan-guo-ce_ch-1_p-18","order":4,"canonicalText":"夫齊合，則趙恐伐，故急兵以示秦。","chunks":[["夫齊合，則趙恐伐，故急兵以示秦。","zh-Hant"]]},{"id":"zhan-guo-ce_ch-1_p-18_s-5","passageId":"zhan-guo-ce_ch-1_p-18","order":5,"canonicalText":"秦以趙攻，與之齊伐趙，其實同理，必不處矣。","chunks":[["秦以趙攻，與之齊伐趙，其實同理，必不處矣。","zh-Hant"]]},{"id":"zhan-guo-ce_ch-1_p-18_s-6","passageId":"zhan-guo-ce_ch-1_p-18","order":6,"canonicalText":"故用祝弗，即天下之理也。","chunks":[["故用祝弗，即天下之理也。","zh-Hant"]]},{"id":"zhan-guo-ce_ch-1_p-18_s-7","passageId":"zhan-guo-ce_ch-1_p-18","order":7,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"zhan-guo-ce_ch-1_p-19_s-1","passageId":"zhan-guo-ce_ch-1_p-19","order":1,"canonicalText":"蘇厲為周最謂蘇秦曰：「君不如令王聽最，以地合於魏，趙故必怒，合於齊，是君以合齊與強楚。","chunks":[["蘇厲為周最謂蘇秦曰：「君不如令王聽最，以地合於魏，趙故必怒，合於齊，是君以合齊與強楚。","zh-Hant"]]},{"id":"zhan-guo-ce_ch-1_p-19_s-2","passageId":"zhan-guo-ce_ch-1_p-19","order":2,"canonicalText":"吏產子君，若欲因最之事，則合齊者，君也；","chunks":[["吏產子君，若欲因最之事，則合齊者，君也；","zh-Hant"]]},{"id":"zhan-guo-ce_ch-1_p-19_s-3","passageId":"zhan-guo-ce_ch-1_p-19","order":3,"canonicalText":"割地者，最也。","chunks":[["割地者，最也。","zh-Hant"]]},{"id":"zhan-guo-ce_ch-1_p-19_s-4","passageId":"zhan-guo-ce_ch-1_p-19","order":4,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"zhan-guo-ce_ch-1_p-20_s-1","passageId":"zhan-guo-ce_ch-1_p-20","order":1,"canonicalText":"謂周最曰：「仇赫之相宋，將以觀秦之應趙、宋，敗三國。","chunks":[["謂周最曰：「仇赫之相宋，將以觀秦之應趙、宋，敗三國。","zh-Hant"]]},{"id":"zhan-guo-ce_ch-1_p-20_s-2","passageId":"zhan-guo-ce_ch-1_p-20","order":2,"canonicalText":"三國不敗，將興趙、宋合於東方以孤秦。","chunks":[["三國不敗，將興趙、宋合於東方以孤秦。","zh-Hant"]]},{"id":"zhan-guo-ce_ch-1_p-20_s-3","passageId":"zhan-guo-ce_ch-1_p-20","order":3,"canonicalText":"亦將觀韓、魏之於秦也，不固，則將與宋敗三國；","chunks":[["亦將觀韓、魏之於秦也，不固，則將與宋敗三國；","zh-Hant"]]},{"id":"zhan-guo-ce_ch-1_p-20_s-4","passageId":"zhan-guo-ce_ch-1_p-20","order":4,"canonicalText":"則賣趙、宋於三國。","chunks":[["則賣趙、宋於三國。","zh-Hant"]]},{"id":"zhan-guo-ce_ch-1_p-20_s-5","passageId":"zhan-guo-ce_ch-1_p-20","order":5,"canonicalText":"公何不令人謂韓、魏之王曰：『欲秦、趙之相賣乎？","chunks":[["公何不令人謂韓、魏之王曰：『欲秦、趙之相賣乎？","zh-Hant"]]},{"id":"zhan-guo-ce_ch-1_p-20_s-6","passageId":"zhan-guo-ce_ch-1_p-20","order":6,"canonicalText":"何不合周最兼相，視之不可離，則秦、趙必相賣以合於王也。","chunks":[["何不合周最兼相，視之不可離，則秦、趙必相賣以合於王也。","zh-Hant"]]},{"id":"zhan-guo-ce_ch-1_p-20_s-7","passageId":"zhan-guo-ce_ch-1_p-20","order":7,"canonicalText":"』」","chunks":[["』」","zh-Hant"]]},{"id":"zhan-guo-ce_ch-1_p-21_s-1","passageId":"zhan-guo-ce_ch-1_p-21","order":1,"canonicalText":"為周最謂魏王曰：「秦知趙之難與齊戰也，將恐齊、趙之合也，必陰勁之。","chunks":[["為周最謂魏王曰：「秦知趙之難與齊戰也，將恐齊、趙之合也，必陰勁之。","zh-Hant"]]},{"id":"zhan-guo-ce_ch-1_p-21_s-2","passageId":"zhan-guo-ce_ch-1_p-21","order":2,"canonicalText":"趙不敢戰，恐秦不己收也，先合於齊。","chunks":[["趙不敢戰，恐秦不己收也，先合於齊。","zh-Hant"]]},{"id":"zhan-guo-ce_ch-1_p-21_s-3","passageId":"zhan-guo-ce_ch-1_p-21","order":3,"canonicalText":"秦、趙爭齊，而王無人焉，不可。","chunks":[["秦、趙爭齊，而王無人焉，不可。","zh-Hant"]]},{"id":"zhan-guo-ce_ch-1_p-21_s-4","passageId":"zhan-guo-ce_ch-1_p-21","order":4,"canonicalText":"王不去周最，合與收齊，而以兵之急則伐齊，無因事也。","chunks":[["王不去周最，合與收齊，而以兵之急則伐齊，無因事也。","zh-Hant"]]},{"id":"zhan-guo-ce_ch-1_p-21_s-5","passageId":"zhan-guo-ce_ch-1_p-21","order":5,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"zhan-guo-ce_ch-1_p-22_s-1","passageId":"zhan-guo-ce_ch-1_p-22","order":1,"canonicalText":"謂周最曰：「魏王以國與先生，貴合於秦以伐齊。","chunks":[["謂周最曰：「魏王以國與先生，貴合於秦以伐齊。","zh-Hant"]]},{"id":"zhan-guo-ce_ch-1_p-22_s-2","passageId":"zhan-guo-ce_ch-1_p-22","order":2,"canonicalText":"薛公故主，輕忘其薛，不顧其先君之丘墓，而公獨脩虛信，為茂行，明群臣，據故主，不與伐齊者產，以忿強秦，不可。","chunks":[["薛公故主，輕忘其薛，不顧其先君之丘墓，而公獨脩虛信，為茂行，明群臣，據故主，不與伐齊者產，以忿強秦，不可。","zh-Hant"]]},{"id":"zhan-guo-ce_ch-1_p-22_s-3","passageId":"zhan-guo-ce_ch-1_p-22","order":3,"canonicalText":"公不如謂魏王、薛公曰：『請為王入齊，天下不能傷齊。","chunks":[["公不如謂魏王、薛公曰：『請為王入齊，天下不能傷齊。","zh-Hant"]]},{"id":"zhan-guo-ce_ch-1_p-22_s-4","passageId":"zhan-guo-ce_ch-1_p-22","order":4,"canonicalText":"而有變，臣請為救之；","chunks":[["而有變，臣請為救之；","zh-Hant"]]},{"id":"zhan-guo-ce_ch-1_p-22_s-5","passageId":"zhan-guo-ce_ch-1_p-22","order":5,"canonicalText":"無變，王遂伐之。","chunks":[["無變，王遂伐之。","zh-Hant"]]},{"id":"zhan-guo-ce_ch-1_p-22_s-6","passageId":"zhan-guo-ce_ch-1_p-22","order":6,"canonicalText":"且臣為齊奴也，如累王之交於天下，不可。","chunks":[["且臣為齊奴也，如累王之交於天下，不可。","zh-Hant"]]},{"id":"zhan-guo-ce_ch-1_p-22_s-7","passageId":"zhan-guo-ce_ch-1_p-22","order":7,"canonicalText":"王為臣賜厚矣，臣入齊，則王亦無齊之累也。","chunks":[["王為臣賜厚矣，臣入齊，則王亦無齊之累也。","zh-Hant"]]},{"id":"zhan-guo-ce_ch-1_p-22_s-8","passageId":"zhan-guo-ce_ch-1_p-22","order":8,"canonicalText":"』」","chunks":[["』」","zh-Hant"]]},{"id":"zhan-guo-ce_ch-1_p-23_s-1","passageId":"zhan-guo-ce_ch-1_p-23","order":1,"canonicalText":"趙取周之祭地，周君患之，告於鄭朝。","chunks":[["趙取周之祭地，周君患之，告於鄭朝。","zh-Hant"]]},{"id":"zhan-guo-ce_ch-1_p-23_s-2","passageId":"zhan-guo-ce_ch-1_p-23","order":2,"canonicalText":"鄭朝曰：「君無患也，臣請以三十金復取之。","chunks":[["鄭朝曰：「君無患也，臣請以三十金復取之。","zh-Hant"]]},{"id":"zhan-guo-ce_ch-1_p-23_s-3","passageId":"zhan-guo-ce_ch-1_p-23","order":3,"canonicalText":"」周君予之，鄭朝獻之趙太卜，因告以祭地事。","chunks":[["」周君予之，鄭朝獻之趙太卜，因告以祭地事。","zh-Hant"]]},{"id":"zhan-guo-ce_ch-1_p-23_s-4","passageId":"zhan-guo-ce_ch-1_p-23","order":4,"canonicalText":"及王病，使卜之。","chunks":[["及王病，使卜之。","zh-Hant"]]},{"id":"zhan-guo-ce_ch-1_p-23_s-5","passageId":"zhan-guo-ce_ch-1_p-23","order":5,"canonicalText":"太卜譴之曰：「周之祭地為祟。","chunks":[["太卜譴之曰：「周之祭地為祟。","zh-Hant"]]},{"id":"zhan-guo-ce_ch-1_p-23_s-6","passageId":"zhan-guo-ce_ch-1_p-23","order":6,"canonicalText":"」趙乃還之。","chunks":[["」趙乃還之。","zh-Hant"]]},{"id":"zhan-guo-ce_ch-1_p-24_s-1","passageId":"zhan-guo-ce_ch-1_p-24","order":1,"canonicalText":"杜赫欲重景翠於周，謂周君曰：「君之國小，盡君子重寶珠玉以事諸侯，不可不察也。","chunks":[["杜赫欲重景翠於周，謂周君曰：「君之國小，盡君子重寶珠玉以事諸侯，不可不察也。","zh-Hant"]]},{"id":"zhan-guo-ce_ch-1_p-24_s-2","passageId":"zhan-guo-ce_ch-1_p-24","order":2,"canonicalText":"譬之如張羅者，張於無鳥之所，則終日無所得矣；","chunks":[["譬之如張羅者，張於無鳥之所，則終日無所得矣；","zh-Hant"]]},{"id":"zhan-guo-ce_ch-1_p-24_s-3","passageId":"zhan-guo-ce_ch-1_p-24","order":3,"canonicalText":"張於多鳥處，則又駭鳥矣；","chunks":[["張於多鳥處，則又駭鳥矣；","zh-Hant"]]},{"id":"zhan-guo-ce_ch-1_p-24_s-4","passageId":"zhan-guo-ce_ch-1_p-24","order":4,"canonicalText":"必須張於有鳥無鳥之際，然後能多得鳥矣。","chunks":[["必須張於有鳥無鳥之際，然後能多得鳥矣。","zh-Hant"]]},{"id":"zhan-guo-ce_ch-1_p-24_s-5","passageId":"zhan-guo-ce_ch-1_p-24","order":5,"canonicalText":"今君將施於大人，大人輕君；","chunks":[["今君將施於大人，大人輕君；","zh-Hant"]]},{"id":"zhan-guo-ce_ch-1_p-24_s-6","passageId":"zhan-guo-ce_ch-1_p-24","order":6,"canonicalText":"施與小人，小人無可以求，又費財焉。","chunks":[["施與小人，小人無可以求，又費財焉。","zh-Hant"]]},{"id":"zhan-guo-ce_ch-1_p-24_s-7","passageId":"zhan-guo-ce_ch-1_p-24","order":7,"canonicalText":"君必施於今之窮士，不必且為大人者，故能得欲矣。","chunks":[["君必施於今之窮士，不必且為大人者，故能得欲矣。","zh-Hant"]]},{"id":"zhan-guo-ce_ch-1_p-24_s-8","passageId":"zhan-guo-ce_ch-1_p-24","order":8,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"zhan-guo-ce_ch-1_p-25_s-1","passageId":"zhan-guo-ce_ch-1_p-25","order":1,"canonicalText":"周共太子死，有五庶子，皆愛之，而無適立也。","chunks":[["周共太子死，有五庶子，皆愛之，而無適立也。","zh-Hant"]]},{"id":"zhan-guo-ce_ch-1_p-25_s-2","passageId":"zhan-guo-ce_ch-1_p-25","order":2,"canonicalText":"司馬翦謂楚王曰：「何不封公子咎，而為之請太子？","chunks":[["司馬翦謂楚王曰：「何不封公子咎，而為之請太子？","zh-Hant"]]},{"id":"zhan-guo-ce_ch-1_p-25_s-3","passageId":"zhan-guo-ce_ch-1_p-25","order":3,"canonicalText":"」左成謂司馬翦曰：「周君不聽，是公之知困而交絕於周也。","chunks":[["」左成謂司馬翦曰：「周君不聽，是公之知困而交絕於周也。","zh-Hant"]]},{"id":"zhan-guo-ce_ch-1_p-25_s-4","passageId":"zhan-guo-ce_ch-1_p-25","order":4,"canonicalText":"不如謂周君曰：『孰欲立也？","chunks":[["不如謂周君曰：『孰欲立也？","zh-Hant"]]},{"id":"zhan-guo-ce_ch-1_p-25_s-5","passageId":"zhan-guo-ce_ch-1_p-25","order":5,"canonicalText":"微告翦，翦今楚王資之以地。","chunks":[["微告翦，翦今楚王資之以地。","zh-Hant"]]},{"id":"zhan-guo-ce_ch-1_p-25_s-6","passageId":"zhan-guo-ce_ch-1_p-25","order":6,"canonicalText":"』公若欲為太子，因令人謂相國御展子，廧夫空曰：『王類欲令若為之。","chunks":[["』公若欲為太子，因令人謂相國御展子，廧夫空曰：『王類欲令若為之。","zh-Hant"]]},{"id":"zhan-guo-ce_ch-1_p-25_s-7","passageId":"zhan-guo-ce_ch-1_p-25","order":7,"canonicalText":"』此健士也，居中不便於相國。","chunks":[["』此健士也，居中不便於相國。","zh-Hant"]]},{"id":"zhan-guo-ce_ch-1_p-25_s-8","passageId":"zhan-guo-ce_ch-1_p-25","order":8,"canonicalText":"」相國令之為太子。","chunks":[["」相國令之為太子。","zh-Hant"]]},{"id":"zhan-guo-ce_ch-1_p-26_s-1","passageId":"zhan-guo-ce_ch-1_p-26","order":1,"canonicalText":"三國隘秦，周令其相之秦，以秦之輕也，留其行。","chunks":[["三國隘秦，周令其相之秦，以秦之輕也，留其行。","zh-Hant"]]},{"id":"zhan-guo-ce_ch-1_p-26_s-2","passageId":"zhan-guo-ce_ch-1_p-26","order":2,"canonicalText":"有人謂相國曰：「秦之輕重，未可知也。","chunks":[["有人謂相國曰：「秦之輕重，未可知也。","zh-Hant"]]},{"id":"zhan-guo-ce_ch-1_p-26_s-3","passageId":"zhan-guo-ce_ch-1_p-26","order":3,"canonicalText":"秦欲知三國之情，公不如遂見秦王曰：『請謂王聽東方之處。","chunks":[["秦欲知三國之情，公不如遂見秦王曰：『請謂王聽東方之處。","zh-Hant"]]},{"id":"zhan-guo-ce_ch-1_p-26_s-4","passageId":"zhan-guo-ce_ch-1_p-26","order":4,"canonicalText":"』秦必重公。","chunks":[["』秦必重公。","zh-Hant"]]},{"id":"zhan-guo-ce_ch-1_p-26_s-5","passageId":"zhan-guo-ce_ch-1_p-26","order":5,"canonicalText":"是公重周，重周以取秦也。","chunks":[["是公重周，重周以取秦也。","zh-Hant"]]},{"id":"zhan-guo-ce_ch-1_p-26_s-6","passageId":"zhan-guo-ce_ch-1_p-26","order":6,"canonicalText":"齊重故有周，而已取秦。","chunks":[["齊重故有周，而已取秦。","zh-Hant"]]},{"id":"zhan-guo-ce_ch-1_p-26_s-7","passageId":"zhan-guo-ce_ch-1_p-26","order":7,"canonicalText":"是周常不失重國之交也。","chunks":[["是周常不失重國之交也。","zh-Hant"]]},{"id":"zhan-guo-ce_ch-1_p-26_s-8","passageId":"zhan-guo-ce_ch-1_p-26","order":8,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"zhan-guo-ce_ch-1_p-27_s-1","passageId":"zhan-guo-ce_ch-1_p-27","order":1,"canonicalText":"昌他亡西周，之東周，盡輸西周之情於東周。","chunks":[["昌他亡西周，之東周，盡輸西周之情於東周。","zh-Hant"]]},{"id":"zhan-guo-ce_ch-1_p-27_s-2","passageId":"zhan-guo-ce_ch-1_p-27","order":2,"canonicalText":"東周大喜，西周大怒。","chunks":[["東周大喜，西周大怒。","zh-Hant"]]},{"id":"zhan-guo-ce_ch-1_p-27_s-3","passageId":"zhan-guo-ce_ch-1_p-27","order":3,"canonicalText":"馮且曰：「臣能殺之。","chunks":[["馮且曰：「臣能殺之。","zh-Hant"]]},{"id":"zhan-guo-ce_ch-1_p-27_s-4","passageId":"zhan-guo-ce_ch-1_p-27","order":4,"canonicalText":"」君予金三十斤。","chunks":[["」君予金三十斤。","zh-Hant"]]},{"id":"zhan-guo-ce_ch-1_p-27_s-5","passageId":"zhan-guo-ce_ch-1_p-27","order":5,"canonicalText":"馮且使人操金與書，間遺昌他書曰：「告昌他，事可成，勉成之；","chunks":[["馮且使人操金與書，間遺昌他書曰：「告昌他，事可成，勉成之；","zh-Hant"]]},{"id":"zhan-guo-ce_ch-1_p-27_s-6","passageId":"zhan-guo-ce_ch-1_p-27","order":6,"canonicalText":"不可成，亟亡來亡來。","chunks":[["不可成，亟亡來亡來。","zh-Hant"]]},{"id":"zhan-guo-ce_ch-1_p-27_s-7","passageId":"zhan-guo-ce_ch-1_p-27","order":7,"canonicalText":"事久且泄，自令身死。","chunks":[["事久且泄，自令身死。","zh-Hant"]]},{"id":"zhan-guo-ce_ch-1_p-27_s-8","passageId":"zhan-guo-ce_ch-1_p-27","order":8,"canonicalText":"」因使人告東周之侯曰：「今夕有姦人當入者矣。","chunks":[["」因使人告東周之侯曰：「今夕有姦人當入者矣。","zh-Hant"]]},{"id":"zhan-guo-ce_ch-1_p-27_s-9","passageId":"zhan-guo-ce_ch-1_p-27","order":9,"canonicalText":"」候得而獻東周，東周立殺昌他。","chunks":[["」候得而獻東周，東周立殺昌他。","zh-Hant"]]},{"id":"zhan-guo-ce_ch-1_p-28_s-1","passageId":"zhan-guo-ce_ch-1_p-28","order":1,"canonicalText":"昭翦與東周惡，或謂照翦曰：「為公畫陰計。","chunks":[["昭翦與東周惡，或謂照翦曰：「為公畫陰計。","zh-Hant"]]},{"id":"zhan-guo-ce_ch-1_p-28_s-2","passageId":"zhan-guo-ce_ch-1_p-28","order":2,"canonicalText":"」照翦曰：「何也？","chunks":[["」照翦曰：「何也？","zh-Hant"]]},{"id":"zhan-guo-ce_ch-1_p-28_s-3","passageId":"zhan-guo-ce_ch-1_p-28","order":3,"canonicalText":"」「西周甚憎東周，嘗欲東周與楚惡，西周必令賊賊公，因宣言東周也，以西周之於王也。","chunks":[["」「西周甚憎東周，嘗欲東周與楚惡，西周必令賊賊公，因宣言東周也，以西周之於王也。","zh-Hant"]]},{"id":"zhan-guo-ce_ch-1_p-28_s-4","passageId":"zhan-guo-ce_ch-1_p-28","order":4,"canonicalText":"」照翦曰：「善。","chunks":[["」照翦曰：「善。","zh-Hant"]]},{"id":"zhan-guo-ce_ch-1_p-28_s-5","passageId":"zhan-guo-ce_ch-1_p-28","order":5,"canonicalText":"吾又恐東周之賊己而以輕西周惡之於楚。","chunks":[["吾又恐東周之賊己而以輕西周惡之於楚。","zh-Hant"]]},{"id":"zhan-guo-ce_ch-1_p-28_s-6","passageId":"zhan-guo-ce_ch-1_p-28","order":6,"canonicalText":"」遽和東周。","chunks":[["」遽和東周。","zh-Hant"]]},{"id":"zhan-guo-ce_ch-1_p-29_s-1","passageId":"zhan-guo-ce_ch-1_p-29","order":1,"canonicalText":"嚴氏為賊，而陽堅與焉。","chunks":[["嚴氏為賊，而陽堅與焉。","zh-Hant"]]},{"id":"zhan-guo-ce_ch-1_p-29_s-2","passageId":"zhan-guo-ce_ch-1_p-29","order":2,"canonicalText":"道周，周君留之十四日，載以乘車駟馬而遣之。","chunks":[["道周，周君留之十四日，載以乘車駟馬而遣之。","zh-Hant"]]},{"id":"zhan-guo-ce_ch-1_p-29_s-3","passageId":"zhan-guo-ce_ch-1_p-29","order":3,"canonicalText":"韓使人讓周，周君患之。","chunks":[["韓使人讓周，周君患之。","zh-Hant"]]},{"id":"zhan-guo-ce_ch-1_p-29_s-4","passageId":"zhan-guo-ce_ch-1_p-29","order":4,"canonicalText":"客謂周君曰：「正語之曰：『寡人知嚴氏之為賊，而陽堅與之，故留之十四日以待命也。","chunks":[["客謂周君曰：「正語之曰：『寡人知嚴氏之為賊，而陽堅與之，故留之十四日以待命也。","zh-Hant"]]},{"id":"zhan-guo-ce_ch-1_p-29_s-5","passageId":"zhan-guo-ce_ch-1_p-29","order":5,"canonicalText":"小國不足亦以容賊，君之使又不至，是以遣之也。","chunks":[["小國不足亦以容賊，君之使又不至，是以遣之也。","zh-Hant"]]},{"id":"zhan-guo-ce_ch-1_p-29_s-6","passageId":"zhan-guo-ce_ch-1_p-29","order":6,"canonicalText":"』」","chunks":[["』」","zh-Hant"]]}]}') as WorkBundle
